quests[12813] = { id = 12813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt euch von den Toten!", description = "Wie gütig... wie großzügig unser Lordkommandant doch ist. Wo er Blumen und Sonnenschein ist, bin ich nur von Hass erfüllt.\n\nEs reicht nicht, ihre erbärmlichen Leben zu beenden - ich möchte sie erniedrigen... entwürdigen!\n\nWas könnte unaussprechlicher sein, als sich in das zu verwandeln, was man hasst? Seine Existenz der Auslöschung einer Sache zu widmen und dann am Ende selbst dazu zu werden?\n\nWie traurig.\n\nBringt diese Tinktur nach Nordwesten zum Hafen des Ansturms. Träufelt sie auf ihre reglosen Leichen und beobachtet das Geschehen - aber meidet die Kathedrale.", sourceObjective = "Setaal Dunkelheiler auf der Todesanhöhe hat Euch die Tinktur des Dunkelheilers gegeben. Träufelt sie auf 10 beliebige Leichen der Einheiten des Scharlachroten Ansturms, die Ihr im Hafen des Ansturms findet.", completion = "<Der Todesritter der Draenei fixiert Euch mit kaltem, starrem Blick, ihre Augen leer und tot. Ein durchtriebenes Grinsen kriecht über ihre Gesichtszüge.>\n\nIch habe noch mehr Tinktur für morgen vorbereitet. Auf dann, gehabt Euch wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[12814] = { id = 12814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr werdet einen Greifen brauchen", description = "Was könnte passender sein, als einen ihrer eigenen Greifen gegen sie einzusetzen? Geht zum Hafen des Ansturms und nehmt die Zügel eines ihrer Greifen aus den toten Klauen seines Reiters.\n\nKehrt mit dem Greifen zu Uzo Todesrufer zurück. Er wird für seine Verwandlung sorgen und Euch weitere Instruktionen geben.", sourceObjective = "Bringt Uzo Todesrufer auf der Todesanhöhe einen Greifen des Ansturms.", progress = "Warum hat das so lange gedauert? Sind ihre Greifen langsam? Dagegen müssen wir etwas unternehmen!", completion = "Oh ja, das wird gut!\n\nTretet zurück... ich werde den Zorn des Blutrituals herbeirufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12815] = { id = 12815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugsperrzone", description = "Nun, da du einen Knochengreifen hast, möchte ich, dass du jeden Tag dort hinunter fliegst und den Luftraum über dem Hafen des Ansturms zu einer Flugverbotszone machst.\n\nIch muss zugeben, Mann, dass es mich nicht wirklich juckt, ob du die Greifenreiter nun mit dem Knochengreifen tötest oder nich'. Doch ich meine, dass es um einiges einfacher sein wird, zu ihnen zu kommen, wenn du den Greifen nimmst.\n\nDavon abgesehen verfügt er über eine Menge netter kleiner Tricks, die du dir zunutze machen kannst.", sourceObjective = "Uzo Todesrufer auf der Todesanhöhe möchte, dass Ihr 10 Greifenreiter des Ansturms tötet.", progress = "Wieso bist du so schnell schon zurück? Wenn mich meine Augen nicht täuschen, dann fliegen diese Jungs vom Ansturm noch immer da rum!", completion = "So soll's sein! Und weißt du was? Das muss jeden Tag, den wir hier sind, gemacht werden.\n\nIch hoffe, dass du morgen wieder zurückkommen wirst. Dein Knochengreif wird auf dich warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12816] = { id = 12816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Geißel bei Silbermond", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Silbermond gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", sourceObjective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Silbermond und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12817] = { id = 12817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Geißel bei der Exodar", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung der Exodar gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", sourceObjective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb der Exodar und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers. Kehrt anschließend zu Leutnant Kregor zurück.", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12818] = { id = 12818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen", description = "Um auf den Punkt zu kommen... Ricket hat mich gebeten, ein paar stärkere Landminen zusammenzubauen, aber mir gehen die Teile aus.\n\nDirekt westlich der Stadt findet Ihr die Überreste unseres letzten Raketenschlittens... Ricket war ein wenig aufgeregt, als sie ihn auftankte, aber vermutlich hätte ich den Einfüllstutzen auch nicht direkt über den Schubdüsen anbringen dürfen. Aus Fehlern lernt man, nicht wahr?\n\nUm den kaputten Schlitten herum sollten jede Menge Ersatzteile liegen... Wieso geht Ihr nicht los, verjagt diese Plünderer und schnappt Euch ein paar Trümmer?", sourceObjective = "Jeer Funksockel auf dem K3 hätte gerne 10 verbrannte Trümmer.", progress = "Wir brauchen etwas, das wir zur Isolation unserer Maschinen gegen die Kälte verwenden können... denk nach, Jeer, denk nach!\n\nOh, he! Habt Ihr ein paar dieser Trümmer für mich?", completion = "Die kann ich gut gebrauchen, danke!\n\nIhr habt da draußen nicht zufällig Dim gesehen? Ich habe ihn schon vor einer ganzen Weile weggeschickt und er kam bisher nicht zurück. Ich hoffe, es geht ihm gut.\n\nWo wir gerade davon sprechen... Ich frage mich, wo Janks ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12819] = { id = 12819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einen Minenwurf entfernt", description = "Verflixt nochmal! Wo sind meine Werkzeuge? Gerade eben waren sie doch noch da.\n\nOh! Ich habe sie wohl vergessen, als ich das Minenfeld im Westen angelegt habe. Das ist ziemlich ärgerlich. Ich wäre sehr erfreut, wenn Ihr mir die Werkzeuge wieder beschaffen könntet. Ihr müsst allerdings vorsichtig sein, wo Ihr hintretet... Ihr solltet denselben Weg benutzen können, auf dem ich herausgekommen bin.\n\nOh, versucht übrigens nicht, dorthin zu fliegen... ich war nämlich so klug und habe Türme aufgestellt, die alles angreifen, was aus der Luft kommt. Und sie kümmern sich nicht sonderlich darum, wer angeflogen kommt.", sourceObjective = "Jeer Funksockel am K3 bittet Euch, dass Ihr Funksockels Werkzeuge aus seinem Minenfeld holt.", progress = "Wenn Janks hier wäre, hätte ich einfach ihn schicken können. Aber... wenn ich's mir recht überlege... bin ich mir nicht sicher, ob ich ihm überhaupt gesagt habe, wo der sichere Weg ist.\n\nNa, zum Glück gibt es hier ja genügend von Euch Abenteurern, nicht wahr?", completion = "Ha ha! Das sind sie! Danke vielmals. Hoffentlich hattet Ihr nicht allzu große Probleme auf Eurem Weg durch das Feld.", sourceObjectiveStatus = "unverified-source-field" }
quests[12820] = { id = 12820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwölf auf einen Streich", description = "Ich warte schon eine Ewigkeit auf diese Minen! Naja, zumindest einige Tage. Warum hat das so lange gedauert?\n\nAlso, die Sache ist die, <Kompadre/meine Gute>... es gibt da einen wilden Haufen von Magnatauren - man kennt sie ja... groß, behaart und unglaublich hässlich. Und sie sind ganz scharf darauf, sich K3 unter den Nagel zu reißen.\n\nWird aber nicht klappen.\n\nWir haben ihnen ein paar Steine in den Weg gelegt... nordöstlich von hier steht unsere Verteidigung. Leider sind die Energievorräte unserer Lasertürme ziemlich eingeschränkt... und da kommen diese Minen ins Spiel! Begebt Euch dorthin und jagt sie in die Luft!", sourceObjective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor 12 Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", completion = "Also... ich habe hier gesessen und habe mich an meiner eigenen Vollkommenheit gelabt, als ich in der Ferne einen Knall gehört habe! Und dann noch einen! Und noch ein Dutzend mehr! Bei dem Gedanken daran, dass all diese Magnatauren und Schneebolde in den Tod rennen, hat sich ein kleines, aber feines Lächeln in mein liebliches Gesicht geschlichen.\n\nWar es so fantastisch, wie ich es mir vorstelle?", sourceObjectiveStatus = "unverified-source-field" }
quests[12821] = { id = 12821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zellenblocktango", description = "Der Pioniertrupp ist bereit! Das heißt, dass jetzt Spaß angesagt ist!\n\nUnserem großen Angriff auf Garm steht nur noch eine Sache im Weg! Ich habe einen Läufer losgeschickt, um einen Teleporter hinter ihm aufzustellen... mit Erfolg, wenn ich das hinzufügen darf. Er ist zurückgekommen, um den Akku zu holen, der für den Betrieb benötigt wird. Aber der Teleporter funktioniert immer noch nicht... das heißt, dass der Akku dort nicht angekommen ist.\n\nIch möchte, dass Ihr auf der anderen Seite von Garms Bann nach dem Transporterakku sucht. Bringt ihn dann weiter östlich zu Garms Erhebung, sobald Ihr ihn gefunden habt, und aktiviert den Teleporter.", sourceObjective = "Ricket am K3 möchte, dass Ihr den Transporterakku findet und damit die Transporterplatte in Garms Erhebung aktiviert.", progress = "Selbst Magnatauren sollten wissen, dass man sich am besten nicht mit Goblins anlegt!", completion = "Hervorragend!\n\n<Ein böses Grinsen breitet sich in Rickets Gesicht aus.>\n\nDie Zerstörung kann beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12822] = { id = 12822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne keine Furcht", description = "Nun verfügen wir über einen offenen Teleporter, doch mein Plan ist äußerst komplex und facettenreich, weswegen er eine fehlerfreie Koordinierung erfordert. Außerdem müssen Vorräte gesammelt werden! Und Truppen rekrutiert! Voraussichtlich kommen Wochen voll harter Arbeit auf Euch zu!\n\nHaha, da habe ich Euch aber einen Schrecken eingejagt, oder? Hier, Freundchen, springt durch den Teleporter und dann auf in den Kampf!! Unsere Pioniere werden Euch Deckung geben... Sie können nicht entkommen!", sourceObjective = "Ricket auf dem K3 möchte, dass Ihr 6 Garmwächter und 8 schneeblinde Anhänger tötet.", completion = "Haha! Das wird diese Rohlinge lehren, unsere Zeit zu verschwenden. Von diesem Tag an wird der Anblick grüner Haut die Herzen aller Magnatauren mit Furcht erfüllen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfekter Plan", description = "Hallo! Ihr wollt Euch uns für den Angriff anschließen, nehme ich an?\n\nIch habe eine besondere Aufgabe für Euch... wir werden dafür sorgen, dass die gesamte Höhle über ihnen einstürzt! Am hinteren Ende der Höhle müsste Frostgeweides Altar zu finden sein. Schleicht Euch heran und bringt dieses dichtgepackte Sprengstoffbündel irgendwo in der Nähe an.\n\nSobald der Sprengstoff erst einmal platziert ist, sollt Ihr noch lange genug bleiben, um sicherzustellen, dass Frostgeweide auch ins Gras beißt, und dann so schnell wie möglich verschwinden! Niemand weiß, wie lange die Höhle intakt bleibt, nachdem das Ding in die Luft geflogen ist!", sourceObjective = "Gino auf Garms Erhebung möchte, dass Ihr das dichtgepackte Sprengstoffbündel in der Nähe von Frostgeweides Altar anbringt und anschließend Tormar Frostgeweide tötet. Danach sollt Ihr entkommen, bevor die Höhle über Euch einbricht.", progress = "Das Sprengstoffbündel ist mein Baby... Ich habe Wochen gebraucht, um es perfekt hinzubekommen. WOCHEN!\n\nDas ist eine lange Zeit... okay.", completion = "Der ganze Berg hat gebebt! War es toll? Ich bin mir sicher, dass es das war! Wie könnte es auch anders sein?\n\nUnd die Erfinderliga beschwert sich darüber, dass alle meine Erfindungen in die Luft fliegen. Natürlich tun sie das! Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Stimmung", description = "Ihr seid aber schnell, das muss ich schon sagen! Danke für die Hilfe mit dem Sprengstoff... ich habe schon seit geraumer Zeit darauf gewartet, diese Erfindung mal richtig zu testen!\n\nGeht zu Ricket und berichtet ihr, dass wir nun keine Probleme mehr mit den Magnatauren haben sollten... meine Pioniere werden sich um die restlichen kümmern.\n\nDanke vielmals!", sourceObjective = "Begebt Euch zu Ricket am K3.", completion = "Ihr habt alles in die Luft gejagt? So wird's gemacht! Ich wette, dass Gino großen Spaß dabei hatte!\n\nWir sind sehr dankbar für Eure große Hilfe, {name}. Wie wäre es im Gegenzug mit einem Geschenk?", sourceObjectiveStatus = "unverified-source-field" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen des Dankes" }
quests[12826] = { id = 12826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leicht instabil", description = "Fantastisch!\n\nNein, nicht Ihr... meine neuen Minen. Ihr seid schon etwas eingebildet, wie? Ich allerdings bin absolut brillant! Mein Intellekt ist unerreicht.\n\nÜber was hatten wir nochmal gesprochen? Ach ja, meine neuen Minen! Neu und verbessert... bereit für jede hinterhältige Idee, die Ricket wieder ausgeheckt haben mag.\n\nSeid doch bitte so nett und bringt sie zu Ricket. Sie ist gleich da drüben... wird also keine allzu lange Reise werden. Seid jedoch vorsichtig, sie ist etwas durchgeknallt.", sourceObjective = "Liefert Jeers verbesserte Landminen bei Ricket am K3 ab.", progress = "Jeer ist fertig mit den Minen? Fein.", completion = "Hach, sind das nicht die süßesten kleinen Babys der Zerstörung, die es auf der Welt gibt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12827] = { id = 12827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rationen-Recycling", description = "Hey! Ein neues Gesicht! Wollt Ihr Ricket vielleicht zur Hand gehen?\n\nWir haben gerade ein etwas unerwartetes Problem... Nahrungsmangel. Ich weiß, ich weiß... wir hätten das voraussehen müssen, aber die Sache ist die: Hier kommen viele Pioniergruppen durch, die jedoch nicht allzu lange bleiben, weswegen wir uns normalerweise keine Sorgen um Langzeitverköstigungen machen müssen. Doch der gute, alte K3 scheint ja jetzt ziemlich gefragt zu sein.\n\nOb es eine bequeme Lösung gibt? Im Westen befinden sich einige Lager der Gnolle... und wie es Gnolle nun einmal so an sich haben, sind auch einige dort in der Gegend verstreut, auf der Suche nach Nahrung. Hättet Ihr etwas dagegen, ein paar ihrer Rationen zu stibitzen?", sourceObjective = "Ricket am K3 bittet Euch, 16 getrocknete Gnollmahlzeiten von den wilden Hügelgnollen in der Nähe zu beschaffen.", progress = "Ah, hallo! Mein Magen knurrt schon... wie ist es gelaufen?", completion = "Hoffentlich haben sie sich nicht allzu sehr geziert, als es darum ging, ihre Kostbarkeiten mit Euch zu teilen. Wir sind bisher immer ziemlich gnädig gewesen, wenn sie sich an unsere Reste gemacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12828] = { id = 12828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welch Eingebung!", description = "Huch, das Zeug ist bösartig! Vielleicht nicht für den Geschmack eines Gnolls oder so, aber ich dachte, dass, was auch immer sie hatten, wenigstens... essbar wäre?\n\nDann müssen wir eben kreativer sein.\n\nTore besitzt einen Sprengstoffspender nördlich der Stadt... nicht weit vom großen Höhleneingang, könnt ihn nicht übersehen. Ich bin sicher, sie hat den Sprengstoff für irgendwelche Grabungsarbeiten vorgesehen, aber ich habe eine bessere Idee.\n\nNehmt Euch etwas davon und bewerft damit eines der Mammuts in der Nähe... die meisten von ihnen halten sich im Westen auf. Sammelt das Fleisch und bringt es zurück.", sourceObjective = "Ricket auf dem K3 möchte, dass ihr ein I.D.S.V. besorgt, damit ein Mammut in die Luft jagt und 8 Stücke herzhaftes Mammutfleisch einsammelt.", progress = "Ich weiß, mein Plan war brillant. Macht Euch keine Sorgen.\n\nFühlt es sich in dieser Präsenz von Großartigkeit nicht wunderbar an? Ein bisschen kribbelnd vielleicht?", completion = "Und es ist bereits erledigt! Ich übertreffe mich zuweilen selbst.\n\nVielen Dank, Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[12829] = { id = 12829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einrücken", description = "He, Ihr! Heiß' Tore. Ich leite den Mineneinsatz hier auf dem K3... oder ich werde es in Kürze tun!\n\nDiese Höhle hier ist voller gruseliger Krabbelviecher. Ich glaube, wir könnten ein paar weniger Spinnen gebrauchen, bevor wir hineingehen - was meint Ihr?", sourceObjective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle möchte, dass Ihr 12 Kristallnetzspinnen tötet.", completion = "Haha! Schön, dass Ihr nix gegen schmutzige Arbeit habt.\n\nBin echt dankbar, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[12830] = { id = 12830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgewinnung des Erzes", description = "Wir gehen hinein!\n\nAls wir ankamen, waren hier ein paar Schneebolde... Ihre Ausgrabungen scheinen jedoch kein glückliches Ende genommen zu haben. Nicht weiter wichtig - wir hätten sowieso bald übernommen.\n\nIch habe einige unserer Bergmänner hineingeschickt, um ein paar Erzproben zu sammeln, die ich zur Kalibrierung unserer Maschinen benutzen möchte, aber sie sind noch nicht zurückgekehrt.\n\nMacht es Euch was aus, da mal hineinzugehen und Eurerseits ein paar Proben für mich zu sammeln? Die Schneebolde besitzen vermutlich ein paar, obwohl ich glaube, dass die meisten von ihnen inzwischen tot sind.", sourceObjective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle hätte gerne, dass Ihr 5 Proben unreines Saroniterz sammelt.", progress = "Habt Ihr'n bisschen Erz für mich?", completion = "Huh, das ist vielleicht ein Gestank! Ihr hattet'n kleines Handgemenge mit diesen Schneebolden, oder?\n\nFinde ich aber gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[12831] = { id = 12831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur teilweise vergessen", description = "Urgh... es fühlt sich an, als hätte ich einen Propeller im Magen.\n\nIch glaube, ich kann gehen, aber seitdem ich im hinteren Teil der Höhle von etwas gebissen wurde, hat sich was ziemlich Bösartiges in meinem Körper ausgebreitet. Die Spinne war größer als die anderen... und sie war auffällig gefärbt.\n\nRicket kann mir vermutlich ein Gegengift brauen, doch sie braucht den Giftbeutel von der, die mich da gebissen hat. Würde es Euch etwas ausmachen, sie für mich zu finden? Ich glaube nicht, dass Tore kommt.\n\nIch stelle mich hier einfach tot und hoffe, dass sie mich in Ruhe lassen.", sourceObjective = "Ein verletzter Goblinminenarbeiter in der Kristallnetzhöhle möchte, dass Ihr ihm einen Eisspitzengiftbeutel von einer Eisspitzenspinne bringt.", progress = "<Der verletzte Goblinminenarbeiter krümmt sich vor Schmerzen.>", completion = "Das sollte reichen... Ich hoffe, Ricket kann mir etwas zusammenmischen. Also, bereit zum Aufbruch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12832] = { id = 12832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittere Trennung", description = "He da - danke Euch! Ich dachte schon, dass ich Futter für die Spinnen werden würde. Aber man sollte sich nicht zu früh freuen - lasst uns hier verdammt nochmal verschwinden!\n\nSagt mir Bescheid, sobald Ihr bereit seid... Beeilt Euch.", sourceObjective = "Begleitet den verletzten Goblinminenarbeiter aus der Kristallnetzhöhle und meldet Euch danach bei Ricket in K3.", completion = "Danke, dass Ihr unserem Minenarbeiter dort geholfen habt, {name}! Ein Gegengift zu mischen dürfte kein großes Problem darstellen.\n\nWenn Ihr Tore wieder trefft, richtet ihr doch bitte aus, dass sie verrückt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12833] = { id = 12833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbestand", description = "Ah, hallo! Ihr seid nicht wie alle anderen Abenteurer davongelaufen? Ihr seid einfach ein Schatz, wie? Ich habe mich schon gefragt, ob ich komisch rieche!\n\nWir könnten hier immer noch etwas Hilfe gebrauchen und Ihr seid genau <der/die> Richtige dafür. Könnt Ihr Euch an diese Magnatauren erinnern? Nun ja, anscheinend ist die Höhle nicht ganz eingestürzt... es sind also noch immer ziemlich viele übrig. So viel zu \"Gino hat sich um sie gekümmert\", wie?\n\nZum Glück hat Jeer mehr als genug Minen hergestellt. Ihr habt verstanden!", sourceObjective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor den Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", completion = "Ich mag Euch. Genau genommen seid Ihr super!\n\nEin Hoch auf {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12834] = { id = 12834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Regen noch Schnee noch explodierender Flieger" }
quests[12835] = { id = 12835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll ausgewachsen" }
quests[12836] = { id = 12836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Dankbarkeit", description = "Ich hätte genau die richtige Arbeit für einen eifrigen Neuling! Wir haben ein Gnollproblem. Man könnte es sogar Gnollplage nennen! Wirklich lästige Kreaturen. Es kommen immer mehr von ihnen angekrochen. Mittlerweile sind sie schon hier und klauen unsere Teile! Unfassbar!\n\nAnfang und Ende dieses Problems ist ihr dreister Anführer, Knarzfell. Ich will, dass Ihr Euch um das \"Ende\" kümmert. Stattet ihm in seinem Lager in den Blendschneehügeln weit draußen im Westen einen Besuch ab.\n\nUnd wenn ich sage \"Besuch abstatten\", meine ich damit \"ihn grausam töten\". Alles klar? Alles klar!", sourceObjective = "Ricket am K3 möchte, dass Ihr Knarzfell tötet.", progress = "Ich mag Ricket, weil sie soooo lecker ist!\n\nOh, willkommen zurück! Wie sieht es mit der Schädlingsbekämpfung aus?", completion = "Echt stark! Ihr seid genau mein {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12837] = { id = 12837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore hat die Waren", sourceObjective = "[PLACEHOLDER] Meldet Euch bei Tore", sourceObjectiveStatus = "unverified-source-field" }
quests[12838] = { id = 12838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationsbeschaffung", description = "Ich muss wissen, was der Scharlachrote Ansturm heute plant. Ihr werdet mir in dieser Sache helfen.\n\nFliegt zum Hafen des Ansturms, durchwühlt die Truhen dort und sucht nach Dokumenten. Sie werden verschlossen sein, tut also alles, was nötig ist, um an die Schlüssel der Anhänger des Scharlachroten Ansturms heranzukommen.", sourceObjective = "Aurochs Grimmbann auf der Todesanhöhe möchte, dass Ihr 5 Geheimdokumente des Ansturms beschafft.", progress = "Habt Ihr die Informationen?", completion = "Gebt sie mir. Ich werde sie durchgehen und nur das Wichtigste heraussuchen. Wenn ich etwas gefunden habe, werde ich mich bei Euch melden.\n\nKommt so oder so morgen wieder. Es ist allgemein bekannt, dass sie jeden Tag ihre Pläne ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12839] = { id = 12839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Plan (des Admirals)", description = "Auf den ersten Blick gleicht diese Notiz jeder anderen Botschaft, nach der Ihr gesucht habt; doch nachdem Ihr ihren Inhalt kurz überflogen habt, seid Ihr vom Gegenteil überzeugt.\n\nDer Brief besagt, dass sich Großadmiral Westwind irgendwo auf der Insel aufhält, sich momentan aber zurückgezogen hat. Er schreibt von einem glorreichen Tag, der bald anbrechen wird und an dem der Scharlachrote Ansturm zuerst über den Lichkönig und danach über den Rest der Welt kommen wird, um endlich wieder Ordnung nach Azeroth zu bringen.\n\nDer Lordkommandant wird das sofort sehen wollen!", sourceObjective = "Bringt dem Lordkommandanten Arete auf der Todesanhöhe die Nachricht vom Großadmiral.", progress = "Der Bericht des Scharlachroten Ansturms muss zu Aurochs Grimmbann gebracht werden.\n\n<Der Lordkommandant sieht Euch erwartungsvoll an - damit seid Ihr entlassen.>", completion = "Eine Nachricht von Westwind? Warum sagt Ihr das nicht gleich?\n\n<Arete reißt Euch den Brief aus der Hand, um ihn zu lesen.>\n\nDieser Narr! Er ist wirklich hier?!\n\n<Der Lordkommandant lacht.>\n\nDas sind neue Nachrichten. Ich frage mich nur: Wie gedenkt er, die Welt zu erobern, nachdem er den Lichkönig gestürzt hat? Was nicht heißt, dass er etwas davon auch nur in seinen wildesten Träumen erreichen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12840] = { id = 12840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streng vertraulich", description = "Wenn jemand weiß, wo sich der Admiral aufhält, dann sicherlich seine Kapitäne auf den Schiffen im Hafen des Ansturms.\n\n<Der Lordkommandant reibt sich die Hände.>\n\nWenn ich mich recht entsinne, lauten ihre Namen Welsington und Hartford. Prügelt die Information aus ihnen heraus und macht danach ihrem kümmerlichen Leben ein Ende.\n\nIch will wissen, wo sich der Großadmiral versteckt!", sourceObjective = "Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr Informationen aus den Kapitänen Welsington und Hartford herausprügelt.", completion = "Sie haben Landgren wieder erweckt? Dann ist er es, der den Aufenthaltsort des Großadmirals kennt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12841] = { id = 12841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Handel der Alten", description = "Ja, es muss der kleine grüne Gefangene sein, den Ihr meint... Eventuell können wir uns gegenseitig helfen.\n\nMit Gewalt kriegt Ihr den Goblin hier nicht raus, zumindest nicht lebendig.\n\nBei meinen Leuten bin ich als Yrkvinn die Illusionistin bekannt. Wie Ihr sehen könnt, haben mich die Hyldnir gefangen genommen.\n\nHätte ich meine Runen, dann könnte ich dafür sorgen, dass Ihr Euch hier ungesehen bewegen könnt. Tiefer im Berg findet Ihr eine Aufseherin namens Syra, die in den Minen patrouilliert. Sie hat meine Runen. Nehmt sie ihr ab, dann reden wir weiter.", sourceObjective = "Lok'lira die Greisin in der verlassenen Mine möchte, dass Ihr Yrkvinns Runen von Aufseherin Syra holt.", progress = "Meine Runen, {name}? Habt Ihr sie?", completion = "Ich war mir nicht sicher, ob Ihr zurückkommen würdet. Der Gedanke daran, was aus mir werden würde, wenn ich zu lange hier bliebe, machte mir schon Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12842] = { id = 12842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen schmieden: Vorbereitung auf den Kampf", description = "Das Zeichen des Krieges ist für immer in Eure Seele gebrannt, Todesritter. Ihr habt die dunkle Kunst des Runenschmiedens erlernt und könnt nun Runen der Macht in Eure Waffen prägen.\n\nBereitet Euch auf den Kampf vor. Kehrt zu einer der Runenschmieden hier im Herzen von Acherus zurück und bedient Euch der neugewonnenen Kunst, um Eure Waffe mit einer Rune der Macht zu versehen!\n\nKehrt zu mir zurück, sobald Eure Klinge vor dunkler Energie leuchtet!", sourceObjective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, mithilfe Eurer Fertigkeit 'Runen schmieden' eine beliebige Rune in Eure runenbeschriebene Seelenklinge zu prägen.\n\nIhr könnt die Prägung auf Eurer Waffe jederzeit durch eine andere ersetzen, solange Ihr Euch in der Nähe einer Runenschmiede befindet.", progress = "Verschwendet nicht meine Zeit, {name}. Wir stehen am Rande einer Apokalypse!", completion = "Merkt Euch diese Worte, {class}: Die Runenschmiede ist ein Instrument der Geißel. Es gibt sie nur in Acherus, Naxxramas und im Herzen der Eiskrone! Ihr könnt Eure Waffen nur an einer Runenschmiede mit Prägungen versehen.\n\nKehrt noch oft zurück, um all Eure Waffen mit Runen zu versehen. Ein {class} muss auf alles vorbereitet sein, das sich ihm in den Weg zu stellen wagt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12843] = { id = 12843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben unsere Männer!", description = "Ihr müsst uns helfen! Wir führten gerade eine Expedition in die Berge durch, um einen Übertragungsturm aufzustellen, als wir angegriffen wurden.\n\nSie sahen aus wie Vrykul, nur dass ihre Haut blau und eisbedeckt war... und es waren nur Frauen! Sie nahmen alle Männer der Expedition mit und ließen uns Frauen gehen. Bitte, {name}! Wir vermuten, dass sie in Sifreldar, dem Dorf oberhalb von K3, festgehalten werden.", sourceObjective = "Gretchen Zischelfunken möchte, dass Ihr nach Sifreldar geht und 5 Goblingefangene befreit.", completion = "Ihr habt es geschafft! Unsere Männer sind zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[12844] = { id = 12844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrüstungsbergung", description = "Bitte, {name}. Als die Hyldnir unsere Männer entführten, nahmen sie auch unsere gesamte Ausrüstung mit. Es ist natürlich viel wichtiger, dass wir unsere Männer wiederbekommen, aber wenn Ihr auf Ausrüstungsgegenstände stoßen solltet, wäre ich Euch sehr dankbar, wenn Ihr sie uns zurückbringen könntet.\n\nIhr findet ihr Dorf direkt über uns im Norden.", sourceObjective = "Gretchen Zischelfunken möchte, dass Ihr 8 Teile der K3-Ausrüstung aus Sifreldar holt, das nördlich des K3 liegt.", progress = "Was macht unsere Ausrüstung, {name}?", completion = "Danke, {name}! Mal sehen, was wir mit diesen Teilen noch anfangen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12846] = { id = 12846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keinen Goblin zurück", description = "Alle unsere Männer sind zurück... dank Euch, {name}! Nun... alle bis auf einen.\n\nMein Bruder Zeev ist laut den anderen immer noch da oben. Offenbar gibt es dort eine Art Mine, in der die Gefangenen arbeiten müssen. Geht dorthin und seht nach, ob Ihr etwas herausfinden könnt.", sourceObjective = "Findet den Eingang zu den verlassenen Minen im Norden von Sifreldar und sucht nach Hinweisen auf Zeev Zischelfunkens Aufenthaltsort.", completion = "Ihr gehört definitiv nicht zu den Hyldnir... warum seid Ihr also hier? Ah... Ihr sucht bestimmt nach dem neuen Gefangenen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12847] = { id = 12847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweite Chancen", description = "Ich hörte, sie hätten einen Erzbischof in ihrer Kathedrale, aber ich hatte ja keine Ahnung, dass sie Landgren wiedererweckt und befördert haben! Die Kathedrale wird schwer bewacht und hat nur einen Eingang, also werdet Ihr Hilfe brauchen.\n\nWir müssen immer noch erfahren, wo sich der Großadmiral aufhält, doch dieses Mal gehen wir kein Risiko ein!\n\nNehmt dieses Gerät. Damit seid Ihr in der Lage, für mich ein Portal zu beschwören, sobald Ihr den Erzbischof getötet habt.\n\nIch hole mir meine Antworten direkt von seiner unterworfenen Seele! Wir werden Großadmiral Westwind finden!", sourceObjective = "Tötet Erzbischof Landgren und beschwört anschließend Aretes Tor in Gegenwart seiner Leiche. Sprecht mit Lordkommandant Arete im Hafen des Ansturms, sobald er sein Verhör mit dem Geist des Erzbischofs beendet hat.", progress = "Ja?", completion = "Verborgene Höhlen auf der Rückseite der Insel. Wie überaus interessant.\n\nNun, wenigstens weiß ich jetzt, wo sich alle meine vermissten Spione befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12848] = { id = 12848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endlose Hunger", description = "Schon bald, {class}, wird sich der unaufhörliche Hunger Eurer bemächtigen - und wenn dies geschieht, werdet Ihr gewaltige Schmerzen erleiden. Es gibt nur ein Heilmittel gegen das Leid: Der Hunger muss gestillt werden.\n\nIch gebe Euch den Schlüssel, der Eure Erlösung sein wird.\n\nDiejenigen, die der dunklen Bruderschaft unwürdig sind, werden ans Herz von Acherus gekettet. Befreit mithilfe des Schlüssels einen unwürdigen Initianden. Erlaubt ihm, seine Ausrüstung zu tragen und mit Euch um seine Freiheit zu kämpfen. Tötet: und der Schmerz wird aufhören. Versagt: und Ihr werdet für alle Ewigkeit leiden müssen.\n\nLebt oder sterbt - die Wahl liegt bei Euch.", sourceObjective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, einen unwürdigen Initianden zu befreien und ihn kaltblütig umzubringen!\n\nEntweder ist es Euer oder ihr Leben!", progress = "Zwei Leben, ein Schlüssel... Enttäuscht mich nicht, {name}.", completion = "Wie erwartet: Mein auserwählter Ritter hat den Sieg davongetragen! Ihr seid nun bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12849] = { id = 12849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Blutes, des Frosts und der unheiligen Kraft", sourceObjective = "In den Hallen des Befehls findet Ihr die Schulen des Bluts, des Frosts und der unheiligen Kraft. Jede dieser Schulen hat einen Lehrer, der Euch mit Wissen der verschiedenen dunklen Künste versorgen kann.\n\nIch, Lord Thorval, bin der Direktor der Schule des Blutes. Lady Alistra herrscht über die Schule der unheiligen Kraft und der Erzlich Amal'thazad über die des Frosts.\n\nIhr müsst jedes Mal wieder hierherkommen, wenn Ihr mehr Macht erlangt habt, und trainieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12850] = { id = 12850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Geißelkommandant Thalanor", description = "Geißelkommandant Thalanor erwartet Eure Ankunft. Ihr findet ihn auf dem Überhang direkt südöstlich unserer derzeitigen Position. Meldet Euch bei ihm und verlangt nach einem Geißelgreifen, der Euch dann zur Todesbresche bringen wird.\n\nPrinz Valanar wird unten auf Euch warten.\n\nLeidet wohl, <Bruder/Schwester>!", sourceObjective = "Meldet Euch beim Geißelkommandanten Thalanor auf dem Balkon auf der ersten Ebene der Schwarzen Festung.", completion = "Der Krieg hat begonnen, {class}! Ich werde Euch meinen besten Greifen zur Verfügung stellen - er wird Euch zur Todesbresche bringen. Chaos, Tod und Zerstörung! Dies alles werdet Ihr einläuten - und noch vieles mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[12851] = { id = 12851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskalte Jagd", description = "Die Prüfung wartet, Frau!\n\nBesitzt Ihr das Herz einer Kriegerkönigin? Oder das einer jammernden Näherin?\n\nHabt Ihr einmal Krieg geschmeckt, werdet Ihr die Antwort wissen.\n\nIhr könnt Eure Mutter anlügen, Eure Schwestern und sogar Euch selbst, doch das Schlachtfeld fördert immer die wahre Natur zutage.\n\nWenn Ihr Eure Vorbereitungen abgeschlossen habt, setzt Euch auf Eiszahn und reitet in die Schlacht. Von seinem Rücken aus müsst Ihr den Regen des Todes auf unseren Feind darniederprasseln lassen!", sourceObjective = "Brijana in Brunnhildar möchte, dass Ihr Eiszahn benutzt und 7 Frostworge und 15 Frostriesen im uralten Wintertal tötet.", progress = "Habt Ihr die Schlacht überlebt, {name}?", completion = "Vielleicht besitzt Ihr wirklich das Herz einer Kriegerin.\n\nDie Zeit wird es zeigen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12852] = { id = 12852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Admiral aufgespürt", description = "Als Hochgeneral Abbendis in Neuherdweiler konfrontiert wurde, schützte sich der Großadmiral selbst vor seiner Flucht mit einer undurchdringlichen Magiesphäre.\n\nIch bin besonders erfahren im Zunichte machen von Magie.\n\nNehmt dies, um es gegen ihn in der versteckten Senke einzusetzen, wenn er seine Sphäre erneut herbeiruft. Ich wünschte, ich könnte dabei sein, um seinen Gesichtsausdruck zu sehen.\n\nErledigt ihn.", sourceObjective = "Lordkommandant Arete möchte, dass Ihr Euch um Großadmiral Westwind kümmert. Kehrt danach zum Lordkommandanten auf die Todesanhöhe zurück.", completion = "MAL'GANIS?!\n\n<Der Lordkommandant lacht hemmungslos.>\n\nDie Narren wurden schon wieder von Dämonen überwältigt und jetzt sind sie vernichtet!\n\nIch vertraue darauf, dass mein liebster {class} lange genug bei uns bleibt, um dabei zu helfen, den Rest von ihnen auszuschalten? Vielleicht kann Euch etwas hiervon überzeugen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12853] = { id = 12853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxusreise!", description = "Hallo, <Kumpel/meine Gute>!\n\nMögt Ihr Spannung und Explosionen?! Wer mag das nicht? Ich kenne genau den richtigen Ort für Euch. Unten bei K3, dem Luxusziel schlechthin, erfinden sie immer neue innovative Sachen und Wege, wie man andere Sachen in die Luft jagen kann! Klingt spannend, was? Falls Ihr bei dem Spaß mitmachen wollt, dann macht Euch noch heute auf den Weg dorthin und sprecht mit Jeer Funksockel!\n\nObligatorische Ausschlussklausel: Zur Teilnahme an oben angedeuteter \"Spannung\" kann unter Umständen körperliche Arbeit vonnöten sein.", sourceObjective = "Sprecht mit Jeer Funksockel am K3 in den Sturmgipfeln.", completion = "Willkommen in K3!\n\nWir sind hier, um zu diesen Gipfeln vorzudringen und einen guten Anteil dieser erstaunlichen Titanenmaschinen in die Finger zu bekommen. Jedoch haben wir in dieser Hinsicht relativ wenig Fortschritte gemacht. Gnolle, Schneebolde, Magnatauren... es ist genug für jedermann da... geschweige denn, dass wir irgendeinen unserer Flieger in der Luft halten können, ohne dass ihre Motoren gleich einfrieren.\n\nJedoch gibt es genug Arbeit zu tun - Ihr helft mit, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[12854] = { id = 12854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Branns Spuren", description = "Nach der Entdeckung von Branns Tagebuch in den Grizzlyhügeln fanden wir nur noch eine einzige Nachricht von Brann. Eine mysteriöse Notiz tauchte im Hauptquartier der Forscherliga auf, ohne Hinweis auf ihren Ursprung. Sie besagte nur, dass wir Brann in seinem Lager treffen und ihm bei seiner Suche helfen sollten.\n\nMeiner Meinung nach müsste sich das Lager nordöstlich von hier befinden, jenseits von Bors Atemstrom und am Fuße einiger Ruinen vom Pfad der Titanen.", sourceObjective = "Beschafft die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Archäologe Andorin in der Eisfestung.", progress = "Habt Ihr Branns Lager gefunden?", completion = "<Archäologe Andorin blickt Euch erwartungsvoll an.>\n\nIhr solltet eigentlich mit Brann zurückkehren, nicht mit einem Stück Papier. Was ist hier los?", sourceObjectiveStatus = "unverified-source-field" }
quests[12855] = { id = 12855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Täter ausschnüffeln", description = "Der Tonfall von Branns Notiz lässt vermuten, dass er etwas mit der Notiz vergraben wollte, möglicherweise eine Art Bündel. Seid Ihr sicher, dass Ihr nicht mehr gefunden habt?\n\nGut, dann müsst Ihr einen der Frosthunde mitnehmen, die die Frosterben zum Fährtenlesen nutzen. Bringt ihn zum zerstörten Lager und lasst ihn Branns Spur aufnehmen.\n\nEr sollte Euch zumindest dorthin führen, wo Ihr seine verschwundenen Habseligkeiten finden könnt, und mit etwas Glück sogar zu Brann selbst.", sourceObjective = "Nutzt das Frosthundhalsband im Verlassenen Lager um herauszufinden, wer Branns Habseligkeiten an sich genommen hat. Wenn Ihr sie finden konntet, setzt das Kommunikationsgerät ein und sprecht mit wem auch immer Ihr Kontakt bekommt.", progress = "Wer seid Ihr?", completion = "Ihr... Ihr seid kein Mitglied der Forscherliga, so weit ich weiß. Aber Ihr habt den Kommunikator gefunden, daher müssen sie Euch geschickt haben. Gut, das ist fast das, was ich erhofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12856] = { id = 12856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltherzig", description = "Einen ehrenhaften Tod auf dem Schlachtfeld zu finden, bringt uns allen Ruhm; in einem Eisblock eingefroren zu sein und auf ewig verspottet zu werden, tut dies nicht.\n\nIhr sollt zur Stadt der Frostriesen Dun Niffelem fliegen, die gleich östlich des uralten Wintertals liegt, und einen gefangenen Protodrachen befreien. Mit seiner Hilfe werdet Ihr dann die gefrorenen Fesseln unserer Schwestern lösen und sie sicher nach Hause bringen können.\n\nNehmt Euch jedoch vor den Keulen der Riesen in Acht, Schwester, wenn Ihr nicht zu den Gefangenen zählen wollt.", sourceObjective = "Brijana gleich östlich von Brunnhildar möchte, dass Ihr nach Dun Niffelem fliegt, 3 gefangene Protodrachen befreit und 9 gefangene Brunnhildar rettet.", progress = "War Eure Mission erfolgreich, Schwester?", completion = "Eure Mühen scheinen sich gelohnt zu haben, Schwester.\n\nIhr habt den Brunnhildar zu Ruhm verholfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12857] = { id = 12857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Rachmähnes Flosse", description = "Von Häuptling Zornklaue:\n\nGetreuer Seelöwe von Häuptling Zornklaue Rachmähne hat Hand gebissen, die es füttern wollte. Zornklaue sagt, dass Rachmähne zu nichts nutzt wegen Drakurutrolle. Häuptling Zornklaue sehr traurig sein, dass er bitten muss, dass Rachmähne getötet wird und seine Flosse als Beweis zurückgebracht wird.\n\nIhr finden Rachmähne im Südosten bei Zornklauensee.\n\nHäuptling Zornklaue leid tun, wegen schlechtem Geschreibe. Das erste Mal, dass ich eines dieser Dinger benutze und Häuptling Zornklaue ist Wolvar, nicht Menschenwesen.", sourceObjective = "Beschafft Rachmähnes Flosse und bringt sie zu Häuptling Zornklaue in der Lichtbresche in Zul'Drak.", progress = "Armer Rachmähne. Er war Geschenk von Schwager.", completion = "<Häuptling Zornklaue weint.>\n\nHatte Rachmähne schon, seit er ein kleiner Heuler. Trauriger Tag für Zornklaue. Zuerst Troll hat Zornklaue angegriffen, dann er machen Rachmähne schlecht. Zornklaue nie mehr mit Troll handeln, nie mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[12858] = { id = 12858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puzzleteile", description = "Dem Licht sei Dank, dass jemand meine Nachricht erhalten hat. Nun, da ich vor den Eisenzwergen sicher bin, muss ich Euch erneut um Eure Hilfe bitten. Ich habe einen Hinweis auf Norgannons Schlüsselstein, der den Zugang zu Ulduars Archiven bewacht, jedoch von den Titanen in zwei Stücke geteilt und versteckt wurde.\n\nEines der Stücke, die Hülle des Schlüsselsteins, wird in der Bibliothek des Erfinders an der Nordküste südlich von Ulduar aufbewahrt. Als Erstes müsst Ihr jedoch die Fragmente einer alten Zugangsscheibe von den Wächtern der Bibliothek beschaffen.", sourceObjective = "Sucht 6 Fragmente der Scheibe des Erfinders und setzt sie damit wieder zusammen.", progress = "Konntet Ihr die Scheibe zusammensetzen?", completion = "Wunderbar! Da wir die Scheibe jetzt haben, müsst Ihr damit das Gewölbe des Erfinders öffnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12859] = { id = 12859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Allerneueste: Feuer noch immer heiß!", description = "Trolle greifen Zornklauenbau an und schmeißen Zornklaue raus! Doch es kommt noch schlimmer: Trolle brennen jetzt Dorf! Das sehr schlecht. Häuptling hat Schamanen der Zornklauen namens Moky befohlen, Feuer zu untersuchen. Ergebnisse sehr überraschend! Feuer noch immer heiß und kann Sachen anzünden.\n\nWerdet Ihr den Zornklauen helfen und das Feuer ausmachen? Moky hat speziellen Feuerlöscher der Zornklauen für Euch. Benutzt speziellen Feuerlöscher, um Feuer im Zornklauenbau gen Südosten zu löschen. Muss manchmal oft sprühen, damit Feuer ausgeht, doch Löscher immer Wasser haben! Zornklauenmagie sehr stark!", sourceObjective = "Schamanenältester Moky in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe des Feuerlöschers der Zornklauen 15 Hüttenfeuer im Zornklauenbau löscht.", completion = "Es ist seltsam, weil ich weiß, dass Ihr Feuer ausgemacht, doch Feuer brennen noch immer. Vielleicht dieses Ding doch nicht so gut, was? Doch Moky Euch für Eure Arbeit bezahlen! Hoffentlich Trolle brennen auch!", sourceObjectiveStatus = "unverified-source-field" }
quests[12860] = { id = 12860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daten schürfen", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Dieser gerissene Mimir muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um, sind dort irgendwelche Datenbanken?\n\nVielleicht ist es das, was Ihr mit der Scheibe machen müsst. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", sourceObjective = "Nutzt die Scheibe des Erfinders, um 7 Teile der versteckten Daten aus den Datenbanken zu beschaffen.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "<Brann sieht die Scheibe in Eurer Hand an.>\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n<Ihr beschreibt den Datenwiederherstellungsprozess.>\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht. Nach allem, was ich gehört habe, könnte ich das über die anderen Bewahrer jedoch nicht behaupten...", sourceObjectiveStatus = "unverified-source-field" }
quests[12861] = { id = 12861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trolle sind durchgedreht!", description = "Drakuru... Ihr wisst, wer dieser Troll ist? Ich denke, dass böse Trolle von Troll namens Drakuru kontrolliert werden. Sie nennen sich Drakurutrolle - deswegen weiß ich das. Nun Ihr sehen, wieso ich Häuptling der Zornklauen. Klügster aller Wolvar!\n\nDoch das nicht der Grund, weshalb ich mit Euch jetzt sprechen. Böse Trolle gekommen und Zornklauen aus Bau geschmissen. Doch Zornklauen, die nicht weglaufen, werden jetzt als Gefangene in Dorf gehalten. Ihr gehen zu Zornklauenbau im Südosten und befreit gefangene Zornklauen. Tötet Trolle für Schlossöffner. Ihr vielleicht töten viele Trolle für viele Schlossöffner.", sourceObjective = "Häuptling Zornklaue in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe der \"Schlossöffner\" von Drakuru, welche die verschiedenen Drakurutrolle bei sich tragen, 8 gefangene Zornklauen befreit.", completion = "Zornklaue Euch danken, {name}. Doch Zornklauenbau wahrscheinlich für immer verloren und Freundschaft mit Trolle auch für immer verloren... und wenn ich denken, mir einfallen, dass Rachmähne auch für immer verloren. Auch Schwager weg. Hrm, Ihr haben Häuptlings Frau gesehen? Ich glaube, sie auch weg.\n\nVielleicht Ihr jetzt gehen. Häuptling ein wenig deprimiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12862] = { id = 12862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles andere versagt", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", sourceObjective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", completion = "Au! Das sah schmerzhaft aus. Aber es war ein ziemlich beeindruckender Auftritt, Bursche!\n\nWillkommen in der Eisfestung! Seid Ihr hier, um uns zu helfen, einen Weg nach Eiskrone zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[12863] = { id = 12863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danksagung", description = "Ah! Danke, dass Ihr gekommen seid, <Kamerad/Fräulein>.\n\nAngesichts Eurer großen Augen und zitternden Hände würde ich vermuten, dass Ihr noch nicht lange hier seid. Da wäre es wohl angebracht, dass Ihr unsere freundlichen Gastgeber kennenlernt!\n\nWir haben einige zusätzliche Heilvorräte... ehrlich gesagt, hatten wir nicht erwartet, derart bequem unterzukommen. Geht voraus, gebt Glorthal dort drüben diese Kiste und helft ihm, wenn's geht. Wir wollen ja nicht, dass sie uns für undankbar halten, wo sie uns doch mit derart offenen Armen empfangen haben.", sourceObjective = "Bringt Glorthal Steifbart in der Eisfestung die Kiste mit Heilvorräten.", progress = "Hallo.", completion = "Heilvorräte? Vielen Dank! Ich weiß zwar ehrlich gesagt nicht genau, was ich damit anfangen soll, aber sie werden uns gewiss nützlich sein.\n\nEs freut mich, Euch kennenzulernen... Euer Volk ist wirklich sehr unterschiedlich. Wir bekommen hier oben nicht sehr oft Besuch - und es ist schön, mal ein paar neue Gesichter zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12864] = { id = 12864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Späher", description = "Da Ihr schon mal hier seid: Es gibt da etwas, bei dem ich Eure Hilfe gebrauchen könnte.\n\nEinige unserer Späher sind schon seit geraumer Zeit nicht mehr zurückgekehrt. Die Gipfel sind eine unwirtliche Gegend... doch die Jungs wissen, was sie tun.\n\nGeht nach Osten... sie sollten sich entlang des Tals namens Bors Atem und in der Nähe von Bors Sturz befinden... in dieser Richtung jedenfalls. Solltet Ihr irgendeinen von ihnen finden, dann muss ich sofort davon erfahren. Wir haben einige Feinde in der Gegend - falls irgendwer von denen ein wenig dreist werden sollte. Besser zu viel vorgewarnt als zu wenig.", sourceObjective = "Glorthal in der Frostfestung hat darum gebeten, im Tal namens Bors Atem und bei Bors Sturz nach Anzeichen für die vermissten Späher der Frosterben zu suchen.", completion = "Wenn ein Späher so lange nicht zurückkommt... dann ist so etwas zu erwarten. Waren es die Harpyien?\n\nKönig Sturmherz lässt uns das ganze Jahr hart trainieren... er hat uns zu sehr guten Kämpfern gemacht. In Zeiten wie diesen verstehe ich, weshalb dies nötig ist. Er ist der weiseste und stärkste Anführer, den ich bis jetzt unter meinesgleichen gesehen habe... lasst Euch von seiner samtweichen Haut nicht täuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12865] = { id = 12865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue Gefährten", description = "Frischfleisch! Schön, Euch kennenzulernen! Ich hätte da etwas Arbeit für Euch, falls Ihr Zeit haben solltet.\n\nIm Osten liegen die Fußmarschen... eine ziemlich unwirtliche Gegend, doch es gibt dort ziemlich viele grasende Rhinozerosse. Unsere Vögel haben Geschmack an ihrem Fleisch gefunden, doch auf die Jagd zu gehen, ist bei all den in der Gegend nistenden Protodrachen immer etwas gefährlich für sie.\n\nFalls Ihr Lust habt, dann geht dorthin und besorgt ein wenig Rhinozerosfleisch, bringt es zurück zu den Gipfeln über uns und verfüttert es an die Adler, die dort nisten.", sourceObjective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 8 Stück frisches Rhinozerosfleisch beschafft und es an die Sturmspitzenadler auf den Gipfeln über der Stadt verfüttert.", completion = "Schönen Dank... und ich bin mir sicher, dass die Adler auch ziemlich dankbar sind. Sie sind mächtige Verbündete und solange sie Euch wohlgesonnen sind, wird es Euch gut ergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12866] = { id = 12866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Aggressoren Einhalt gebieten", description = "Verdammte Harpyien. Ich kann mich schon gar nicht mehr daran erinnern, wie oft wir die Viecher schon zu Kleinholz verarbeitet haben... und nach jedem Kampf geben sie für eine Weile Ruhe. Ich hatte gedacht, dass sie es dieses Mal verstanden hätten.\n\nDoch anscheinend nicht.\n\nIhr Gedächtnis mag vielleicht ein wenig kurz sein, doch wenn man genug von ihnen totschlägt, lassen sie einen in Ruhe. Würdet Ihr hinunter in die Täler gen Norden und Osten gehen und einen Großteil von ihnen beseitigen?", sourceObjective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr 8 Frostfederkreischerinnen und 8 Frostfederhexen tötet.", completion = "Es ist Drecksarbeit, ich weiß, doch wir sind Euch dafür dankbar. Was war nun noch mal der Name, den der Späher genannt hat... Sirana?", sourceObjectiveStatus = "unverified-source-field" }
quests[12867] = { id = 12867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Babydiebe", description = "Wenn Ihr noch vor ein paar Wochen nach oben geblickt hättet, hättet Ihr Dutzende dieser wunderschönen Adler durch die Lüfte gleiten sehen. Jetzt sieht man nur noch ein paar, wenn überhaupt. Sie bleiben jetzt fast die ganze Zeit bei ihren Nestern, weil die Harpyien einige ihrer Eier gestohlen haben.\n\nDie Harpyien haben Geschmack am Fleisch der Adler gefunden, wie es scheint... Die kranken Miststücke kümmern sich lange genug um die Eier, bis diese ausschlüpfen, um sich dann an den Jungen gütlich zu tun. Geht zu den Tälern im Norden oder Osten und findet die Eier... Bringt sie hierher und ich werde sie wieder zurück in die Nester legen.", sourceObjective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 15 Eier eines Sturmspitzenadlers zurückbringt.", progress = "Wir werden uns um dieses Harpyienproblem kümmern... Die Adler werden schon bald wieder frei durch die Lüfte segeln können.", completion = "Sehr gut, {name}. Ihr macht Euch schnell Freunde.\n\nWenn Ihr bald wieder vorbeischaut, dann wird sich mit Sicherheit einer finden lassen, der Euch auf ihm reiten lässt... Sie sollten jetzt wissen, dass man Euch vertrauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12868] = { id = 12868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirana Eisschrei", description = "Diese Sirana Eisschrei scheint diejenige zu sein, die die Harpyien zu noch mehr Aggressivität anstachelt. Ich vermute, dass sie ihre Angriffe bald einstellen werden, wenn wir ihr den Garaus machen.\n\nEiner unserer Sturmreiter behauptet, sie am Gipfel nordwestlich von hier gesehen zu haben. Findet das Weib und macht ihm ein Ende, ein für alle Mal.", sourceObjective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr Sirana Eisschrei tötet.", completion = "Es ist also vollbracht. Vielen Dank.\n\nIch habe mit Fjorlin gesprochen - er sagte, dass seine Männer die Harpyien unter Kontrolle halten werden. Solange wir sie im Auge behalten, werden sie nicht so schnell wieder den Mut haben, meine Leute anzugreifen.\n\nMir ist klar, dass das keine sehr angenehme Aufgabe war - nehmt dies als Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12869] = { id = 12869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu weit getrieben", description = "Ihr seid mit Loken dort gewesen, nicht wahr? Die Eisenzwerge haben Veranus, die Brutmutter der Protodrachen, gefangen genommen. Die Drachen scheinen nicht im Mindesten froh über die Situation zu sein... sie sind sehr aggressiv geworden.\n\nSie sind ins Sturmspitzengebiet eingedrungen und werden von den Adlern mit allen Mitteln bekämpft. Ihr wisst, auf welcher Seite wir stehen... Sie haben schon immer zu uns gehalten - es ist Zeit, den Gefallen zu erwidern.\n\nKönig Sturmherz hat mir diesen Hammer hinterlassen. Macht von ihm gut Gebrauch und seht zu, dass ich ihn wieder zurückbekomme.", sourceObjective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr auf einem Sturmspitzenadler 16 Sturmgipfelwyrm in den Fußmarschen niederstreckt.", progress = "Die Situation ist völlig außer Kontrolle geraten.", completion = "So wie ich das sehe, sind die Drachen nicht so leicht zu entmutigen. Schaut morgen wieder hier vorbei, falls Ihr Zeit haben solltet, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12870] = { id = 12870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Relikte", description = "Seid gegrüßt!\n\nBevor Ihr Eure große Suche, Euer großes Abenteuer antretet, könnte Ich Euch um einen kleinen Gefallen bitten, <Kamerad/Fräulein>?\n\nIn diesen Bergen gibt es lauter kostbare Relikte und Schmuckstücke... Dieser Ort ist für die Liga wie ein wahrgewordener Traum. Ich wäre Euch sehr dankbar, wenn Ihr Schätze dieser Art zu mir bringen könntet, falls Ihr über welche stolpern solltet. Für die Unannehmlichkeiten könnt Ihr sogar etwas von meinem Bier haben! Glaubt mir, <Kamerad/Fräulein>, das ist ein gutes Geschäft!", sourceObjective = "Bringt 10 Relikte von Ulduar zu Rork Spitzkinn in die Eisfestung.", progress = "Habt Ihr ein paar dieser Relikte gefunden?", completion = "Wunderschön! Gut gemacht habt Ihr das.\n\nKippen wir uns einen hinter die Birne! Lasst uns diesen glorreichen Fund feiern!", sourceObjectiveStatus = "unverified-source-field" }
quests[12871] = { id = 12871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von der Forscherliga", description = "Interessant. Ich kann keine Schließmechanismen auf der Schale erkennen. Das lässt mich darauf schließen, dass man mehr als nur das andere Teil finden muss, um den Schlüsselstein zusammenzufügen.\n\nBringt die Schale zurück zum Expeditionsleiter Lagnus in der Eisfestung. Sobald er dann erst einmal seine Scheu überwunden hat, sollte er anhand der Schale herausfinden können, wie der Kern aussieht. Vielleicht können sie auch die Frostzwerge dazu bringen, bei der Suche zu helfen.\n\nIch werde versuchen herauszufinden, wie sich die zwei Teile zusammenfügen lassen. Wir werden uns wiedersehen, wenn wir beide etwas weiter gekommen sind.", sourceObjective = "Bringt Norgannons Schale zu Lagnus in die Eisfestung.", progress = "Hallo!", completion = "Bei Muradins Bart! Ist das hier das, von dem ich denke, dass es das ist?! Brann hat sich diesmal wirklich selbst übertroffen... wie auch Ihr in dem Fall! Die Jungs Zuhause werden das niemals glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12872] = { id = 12872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannons Schale", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", sourceObjective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", progress = "Steht nicht nur so da, zeigt mir die Schale!", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, {name}. Wenn ich wieder in Eisenschmiede bin, werde ich Euch als Ehrenmitglied der Forscherliga vorschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12873] = { id = 12873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König der Frosterben", description = "Auf jeden Fall... Ich weiß ganz genau, wie der Kern aussieht. Falls ihn irgendeiner der Frosterben gesehen haben sollte, dann wird ihm die Beschreibung mit Sicherheit bekannt vorkommen.\n\nWir haben keine Zeit zu verlieren, lasst uns also gleich zur Sache kommen. Geht zu König Sturmherz und erbittet seine Hilfe... Er wird sicherlich jemanden kennen, der uns helfen kann, den Kern zu finden. Und seid freundlich zu ihm - in dieser Gegend wird er sehr respektiert.", sourceObjective = "Sprecht mit Yorg Sturmherz in der Eisfestung.", completion = "Norgannons Kern? Noch nie davon gehört. Kann jedoch gut sein, dass ich jemanden kenne, der es hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12874] = { id = 12874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eifer der Frosterben", description = "Ich wäre ja durchaus bereit, Reisenden in Not Unterkunft zu bieten, aber ich möchte mich auch nur ungern in Eure Angelegenheiten einmischen.\n\nIch sag Euch was... meine Leute sind ehrliche und aufrichtige Krieger. An dem Tag, an dem ein Frosterbe zum Mann wird, muss er sich im Kampf beweisen. Er muss uns zeigen, dass er sich nicht von Größe einschüchtern lässt.\n\nBeweist mir, dass Ihr genau so stark und wild seid wie meine Männer, dann werde ich dafür sorgen, dass sie Euch ein Ohr schenken oder Euch ihre Klinge zur Verfügung stellen. Sprecht an der Klippe im Süden mit Fjorlin, er wird Euch auf die Probe stellen.", sourceObjective = "Yorg Sturmherz in der Eisfestung hat Euch gebeten, mit Fjorlin Frostbraue zu sprechen und Euch der Herausforderung zu stellen.", completion = "Ha! Ich bin beeindruckt... vielleicht fließt doch etwas Frosterbenblut durch Eure Adern? Ihr steht jedoch zu Euren Worten, und genau das wollte ich wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12875] = { id = 12875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erfahrener Führer", description = "Ich weiß nicht, wo sich dieser Kern versteckt, das war Euch doch klar? Aber ich habe gesagt, dass ich Euch helfe, und das werde ich auch.\n\nEs gibt da einen Einsiedler namens Drom Frostgriff, der in einer Höhle nördlich von hier lebt... unten im Tal. Wir haben uns ein wenig von den Titanen entfernt, da es nur noch so wenige gibt, aber Drom ist den alten Wegen treu geblieben... Er behält ihre wichtigsten Plätze im Auge und unterhält sich häufig mit dem Bewahrer Creteus.\n\nIhr könnt ihn vermutlich im hinteren Teil seiner Höhle antreffen... sagt ihm, dass ich Euch schicke, dann wird er Euch helfen.", sourceObjective = "Macht Drom Frostgriff ausfindig.", completion = "<Drom hustet ein wenig Blut aus.>\n\nNorgannons Kern, sagt Ihr? Ich habe einige Tage damit verbracht, mehr darüber herauszufinden, aber das scheint eines der Relikte zu sein, die noch immer gut beschützt sind. Vermutlich aus gutem Grund.\n\nWenn König Sturmherz Euch hergeschickt hat, dann muss er etwas Nobles in Euch sehen... und ich werde mich dem Wunsch meines Königs nicht widersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12876] = { id = 12876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwillkommene Gäste", description = "Unsere Späher haben im Tal nördlich von hier Eisenzwerge gesichtet. Ich hab' zufällig mitgekriegt, dass König Sturmherz Euch ausschickt, um Drom zu besuchen, und ehrlich gesagt mach' ich mir wegen denen ein bisschen Sorgen.\n\nFalls Ihr auf Eurem Weg auf Eisenzwerge stoßt, zeigt keine Gnade und erledigt sie schnell für mich, in Ordnung? Ich glaub' nicht, dass sie schon wissen, wo genau wir sind oder wie man hierher kommt, und ich will, dass das auch so bleibt.", sourceObjective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr 10 Sturmgeschmiedete Eindringlinge tötet.", completion = "Schlechte Neuigkeiten, Kamerad. Diese Eisenzwerge scheinen immer mehr zu werden... wir haben sie über die ganzen Berge verstreut gesehen. Das riecht nach Krieg.\n\nHabt Dank dafür, dass Ihr Euch um dieses Pack gekümmert habt... wir haben dadurch etwas mehr Zeit gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12877] = { id = 12877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einsame Wächter", description = "Ich habe den Kern nie gefunden... doch ich habe oft mit dem Hüter Creteus gesprochen und das, was er gesagt oder besser: das, was er nicht gesagt hat, hat ihn verraten. Ihr findet Creteus auf der anderen Seite der Berge gen Osten in den Fußmarschen, wo er über die Maschine der Schöpfer Wache hält. Es kann gut sein, dass sich der Kern dort befindet, doch zuerst müsst Ihr Creteus' Gunst erlangen.\n\nDie Eisenzwerge sind hier gewesen und haben nach etwas gesucht... es ist gut möglich, dass sie nach dem Kern gesucht haben. Sie haben mir meinen Ring weggenommen. Findet ihren Anführer, erlangt meinen Ring zurück und legt diesen dann Creteus vor, damit er weiß, dass ich Euch geschickt habe.", sourceObjective = "Beschafft Frostgriffs Siegelring von einem der Eisenzwergüberwacher und bringt ihn zu Creteus in den Fußmarschen.", progress = "Hallo, {race}.\n\nEs erfreut mich, zu sehen, dass Ihr Euch dazu entschlossen habt, meine Bekanntschaft nicht mit der Klinge, sondern mit der Zunge zu machen. Meinen Erfahrungen nach scheint dies in letzter Zeit eine immer seltenere Eigenschaft unter Euresgleichen zu sein.", completion = "Droms Ring? Dass er Euch nicht selbst vorgestellt hat, lässt mich darauf schließen, dass es ihm nicht gut geht. Tut mir leid, das zu hören. Drom ist ein nobler Zwerg, wenn auch ein neugieriger.\n\nNun denn, weshalb seid Ihr hierher gekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12878] = { id = 12878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das versteckte Relikt", description = "Während Eurer Abwesenheit wurde mir das Privileg einer Unterhaltung mit dem Zwerg Brann Bronzebart zuteil. Er gab mir zu verstehen, dass seine Aufgabe die Suche nach dem Schlüsselstein sei. Es stimmt mich zufrieden, dass seine Absichten zufriedenstellend sind... Dieser Zwerg, so glaube ich, könnte das Wesen sein, für das der Schlüsselstein geschaffen wurde.\n\nNorgannons Kern befindet sich im eisigen Grab gen Südosten. Seine Bewacher sind uralte Wesen aus Eis. Sie werden Euch nicht willkommen heißen. Besiegt die Wächter und beschafft den Schlüsselstein. Ihr habt meinen Segen, {race}.", sourceObjective = "Creteus in den Fußmarschen hat Euch Informationen zukommen lassen, mit deren Hilfe Ihr Norgannons Kern finden könnt. Macht Euch auf den Weg dorthin.", completion = "<Die Truhe öffnet sich. Luft entweicht und erfüllt die Kammer mit einem modrigen Geruch, als läge dort etwas, das schon seit unzähligen Jahren hier gewesen ist. Norgannons Kern liegt auf dem Boden der Truhe, von den Jahren unberührt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12879] = { id = 12879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Frosterbenkönigs", description = "<Als Ihr den Kern aus der Kiste nehmt, hört Ihr donnernde Schritte im Gang, die sich Euch nähern. In der Ferne ist leise der Klang eines Kampfes zu vernehmen.>", sourceObjective = "Bringt Norgannons Kern zu Creteus in die Fußmarschen.", progress = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher. {race}, konntet Ihr den Kern finden?", completion = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher.\n\n{race}, ich freue mich, dass Ihr vor diesen Monstrositäten zum Kern gelangen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12880] = { id = 12880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterforscher", description = "Zum Kombinieren des Schlüsselsteins benötigt Ihr Norgannons Bindung - ein Gerät, das sich in der Maschine des Schöpfers in der großen Grube neben uns befindet. Brann müsste inzwischen mit der anderen Hälfte des Schlüsselsteins da unten sein. Ich habe ihn in Bezug auf den Gebrauch des Geräts instruiert. Er erwartet Euch.\n\nIch werde tun, was ich kann, um die Eisenzwerge abzulenken, aber ich weiß nicht, wie lange ich sie aufhalten kann. König Sturmherz wird in Kürze mit ein paar seiner Männer in der Eisfestung eintreffen, um bei der Verteidigung zu helfen. Bitte beeilt Euch, {race}.", sourceObjective = "Bringt Norgannons Kern zu Brann Bronzebart in die Maschine der Schöpfer.", progress = "Hallöchen, Kamerad! Schön, Euch zu sehen. Habt Ihr ihn gefunden?", completion = "Ihr seid brillant! Wirklich brillant. Das ist wahrlich ein glorreicher Tag.\n\nSchnell, gebt mir den Kern, bevor die Zwerge hier auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12881] = { id = 12881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Bronzebart" }
quests[12882] = { id = 12882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Relikte", description = "Willkommen auf den Gipfeln.\n\nIch habe eine einfache Bitte an Euch, bevor Ihr Euren großen Ausflug antretet - wo auch immer dieser hinführen mag. In diesen Bergen verstreut gibt es uralte Ulduarschätze und -relikte. Die meisten befinden sich höchstwahrscheinlich im Besitz der verschiedenen empfindsamen Wesen dort.\n\nBringt jeden dieser Schätze zu mir zurück und ich werde Euch angemessen belohnen. Ich habe viele Sorten Starkbier - vielleicht werde ich Euch sogar mittrinken lassen.", sourceObjective = "Bringt 10 Relikte von Ulduar zu Olut Bierbauch bei der Absturzstelle Grom'ash.", progress = "Konntet Ihr die Relikte, von denen ich sprach, finden?", completion = "Die werden reichen! Herzlichen Dank. Ein Humpen für Eure Müh'?", sourceObjectiveStatus = "unverified-source-field" }
quests[12883] = { id = 12883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Drakuru", description = "Die Diener vernehmen den Ruf Eures Meisters! Der Lichkönig wird Drakuru die volle Kontrolle über die Armeen der Geißel in Zul'Drak geben. Uns wurde befohlen, alles zu töten.\n\nALLES MUSS STERBEN!\n\nWir werden die Leichen auf dem Todesfeld sammeln und sie dann zu Prinz Navarius in Zeramas schicken, damit sie dort in Diener der Geißel verwandelt werden! Nichts wird verschwendet, solange Drakuru ein Auge aufhält!\n\nBald werden wir das Blut der Propheten trinken und stärker werden, als jemals zuvor! Zul'Drak und Gundrak werden an die Geißel fallen!", sourceObjective = "Bringt Drakurus Befehle zu Kreuzfahrerlord Lantinga in der Lichtbresche in Zul'Drak.", progress = "Drakuru, hm? Ich habe den Namen schon einmal gehört...", completion = "Wenn dies derselbe Drakuru ist, wie der aus der Feste Drak'Tharon, dann... dann werden wir Hilfe von außerhalb benötigen.\n\nIn der Nähe sind Todesritter von Acherus stationiert. Sie folgen offensichtlich derselben Spur der Verwüstung, welche die Geißel hinterlassen hat, wie der Argentumkreuzzug. Da die Hälfte unserer Armee an der Argentumwache benötigt wird, um dort gegen die verrückt gewordenen Drakkaritrolle zu kämpfen, werden wir uns mit den Rittern der Schwarzen Klinge zusammentun müssen.\n\n<Lantinga murmelt vor sich hin.>\n\nIch hatte gehofft, dass ich diese Gauner nach der Sache bei der Kapelle des hoffnungsvollen Lichts nie wieder sehen müsste...", sourceObjectiveStatus = "unverified-source-field" }
quests[12884] = { id = 12884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarze Wacht", description = "Westlich von hier auf der anderen Seite der zerstörten Straßen und Gebäude liegt die Schwarze Wacht - ein Lager der Todesritter.\n\n<Kreuzfahrerlord Lantinga rollt die Schriftrolle mit Drakurus Befehlen wieder zusammen.>\n\nNehmt diese Befehle und liefert sie bei Stefan Vadu ab; er ist der leitende Todesritter in der Schwarzen Wacht. Lasst ihn wissen, dass der Argentumkreuzzug sich um Prinz Navarius kümmern wird und dass sie sich um Drakuru kümmern werden müssen.\n\nSeid vorsichtig, {name}. Der Weg zur Schwarzen Wacht wimmelt nur so von Dienern der Geißel.", sourceObjective = "Liefert Drakurus Befehle bei Stefan Vadu in der Schwarzen Wacht in Zul'Drak ab.", progress = "Was habt Ihr denn da, {race}?", completion = "<Stefan liest sich das Schreiben durch, zerknüllt es und wirf es ins Feuer.>\n\nNichts Neues. Der Argentumkreuzzug ist wieder einmal etwas zu langsam. Wir haben diesen Drakuru schon seit den Grizzlyhügeln verfolgt. Er ist zur Vernichtung bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12885] = { id = 12885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbannten von Ulduar", description = "Die Sturmgipfel sind faszinierend, aber hier findet Ihr mehr als bloß Titanenruinen. Jeder, der hier lebt, muss die Bedrohung durch Loken und seine Diener ertragen.\n\nEr hat seine Lieblingsdiener, die Eisenzwerge, auf einen brutalen Feldzug gegen alle Kreaturen aus Stein geschickt und die Irdenen aus Ulduar verbannt, die in Bergfels' Zuflucht an einem Berghang westlich der Bibliothek des Erfinders Unterschlupf fanden. Die dortigen Eisenzwerge setzen Bergfels und seinen Brüdern jedoch ordentlich zu. Findet sie und helft ihnen, {name}.", sourceObjective = "Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht.", completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf gegen Loken und seinen Anhängern, im Kampf um Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12886] = { id = 12886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Drakkensryd", description = "Das ist es, Ihr habt alle Aufgaben des Hildarthings bestanden... alle bis auf eine. Ihr seid unter den besten und wildesten unserer Schwestern aufgewachsen.\n\nDie letzte Aufgabe steht nun bevor. Der Drakkensryd - die wahre Prüfung des Werts und Kampfgeistes einer Hyldnir. Dort gibt es nur Euch, Euren Reitdrachen, eine Kettenharpune und einige Eurer Schwestern, mit denen Ihr um die Vorherrschaft kämpfen werdet.\n\nVerschont niemanden, dies wird nicht geduldet.", sourceObjective = "Verwendet die Hyldnirharpune, um 10 Drachenreiterinnen des Hildarthings im Tempel der Stürme zu besiegen. Wendet die Hyldnirharpune auf ein Säulenornament an, um den Drakkensryd zu verlassen. Sprecht anschließend mit Thorim, solltet Ihr erfolgreich gewesen sein.", progress = "Fort mit Euch!", completion = "Sif... bist du das?", sourceObjectiveStatus = "unverified-source-field" }
quests[12887] = { id = 12887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Spaß und Spiele", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich habe einen Kontaktmann in der Gruppe, der um Hilfe gebeten hat.\n\nDer erste Schritt ist, den Lichkönig zu blenden. Er nutzt ein Gerät namens Okular, das über den Türmen des Gewölbes schwebt, um das Gebiet zu überwachen.\n\nUnsere Zwerge haben etwas geschaffen, das sich dagegen einsetzen lässt. Wenn das 'Auge' zerstört ist, findet Baron Splitter auf dem Gelände des Gewölbes. Er wird so tun, als stünde er noch immer unter der Kontrolle des Lichkönigs.", sourceObjective = "Zerstört das Okular und erstattet danach Baron Splitter im Schattengewölbe Bericht.", completion = "Vielleicht können wir jetzt wirklich etwas bewegen. Aber lasst Euch nicht täuschen, der Lichkönig kann immer noch durch seine Diener der Geißel 'sehen'.\n\nDarum seid Ihr hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12888] = { id = 12888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SCHROTT-E", description = "Mit dieser Karte erhält der Benutzer Zugriff auf die Steuerkonsole des Schrottbots genannt SCHROTT-E. Möglich sind Wartung des Roboters und Umprogrammierung seiner Direktiven.\n\nSCHROTT-E scheint dem Inneren der Bibliothek des Erfinders zugewiesen worden zu sein. Die Karte zeigt eine Liste aller defekten Komponenten und ausgefallenen Systeme des Bots. Mit den entsprechenden Teilen kann er jedoch wieder funktionstüchtig gemacht werden.", sourceObjective = "Bringt die Zugriffskarte für SCHROTT-E sowie 4 Hand voll Kobaltbolzen und 5 überladene Kondensatoren zu SCHROTT-E in die Bibliothek des Erfinders.", progress = "<Ihr öffnet die Zugangsklappe von SCHROTT-E.>", completion = "<Ihr beginnt, die auf der Zugriffskarte angegebenen Reparaturen auszuführen. Als sie beendet sind, schließt Ihr die Zugangsklappe und schaltet den Stromschalter ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12889] = { id = 12889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prototypenkonsole", description = "Bezeichnung: SCHROTT-E.\n\nDirektive: Instandhaltung von Konsolen und Datenbanken der Bibliothek des Erfinders in Hüter Mimirs Abwesenheit.\n\nZeit seit letztem Instandhaltungszyklus: 489 Tage.\n\nStatus der schematischen Daten: unbekannt.\n\nAktuelle Aufgaben: Reparatur der Prototypenkonsole.", sourceObjective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.", completion = "Ihr untersucht den Bildschirm der Prototypenkonsole. Mindestens einer von Mimirs Bauplänen scheint die lange Zeit zwischen den Instandhaltungszyklen überstanden zu haben. Den angezeigten Diagrammen und Anweisungen der Bauplandatei nach zu urteilen, könntet Ihr den abgebildeten Mechagnom mit Leichtigkeit selbst zusammenbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12890] = { id = 12890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Größe von Bedeutung wäre..." }
quests[12891] = { id = 12891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich habe da eine Idee, aber zuerst...", description = "Als ich im, äh, Dienste des Lichkönigs stand, bedienten wir uns oft eines Geräts namens \"Herrschaftsstab\", mit dem wir dafür sorgten, dass einige der intelligenteren Diener der Geißel nicht aus der Reihe tanzten.\n\nIhr müsst mir dabei assistieren, einen neuen zu konstruieren.\n\nZu Eurem Glück sind alle notwendigen Komponenten verfügbar: eine Kultistenrute, ein Monstrositätenhaken, ein Spukseil und eine Handvoll Geißelessenz.\n\nDies sollte nicht allzu schwierig werden, {class}.", sourceObjective = "Baron Splitter im Schattengewölbe hat Euch gebeten, eine Kultistenrute, einen Monstrositätenhaken, ein Spukseil und 5 Geißelessenzen zu besorgen.", progress = "Wenn es Euch gelungen ist, die Dinge zu besorgen, um die ich Euch gebeten habe, baue ich das Gerät - mit ein paar Modifikationen zu unseren Gunsten - und dann sind wir im Geschäft.", completion = "Schnell, gebt sie mir und bleibt außer Sichtweite!\n\nDie Rute, der Haken und das Seil sind miteinander kombiniert in ihrem Nutzen sehr selbsterklärend. Ich brauche das Ergebnis nur mit den Essenzen zu durchziehen und dann werden wir fortfahren können.\n\nIn seiner Bauweise mag es zwar banal sein, in seiner Anwendung ist es jedoch außergewöhnlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[12892] = { id = 12892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Spaß und Spiele", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich stehe mit einem von ihnen in Kontakt, der uns um Hilfe gebeten hat.\n\nDer erste Schritt wird es sein, dem Lichkönig die Sicht zu rauben. Er verwendet zur Überwachung des Gebiets ein Gerät namens \"Okular\", das über den Türmen des Gewölbes schwebt.\n\nUnsere Goblins haben etwas konstruiert, das Ihr dagegen einsetzen könnt. Nachdem das \"Auge\" zerstört ist, müsst Ihr Baron Splitter auf dem Gelände des Gewölbes finden. Er gibt vor, immer noch unter der Kontrolle des Lichkönigs zu stehen.", sourceObjective = "Zerstört das Okular und erstattet Bericht bei Baron Splitter im Schattengewölbe.", completion = "Womöglich sind wir nun imstande, wirklich etwas zu unternehmen. Lasst Euch jedoch nicht täuschen, der Lichkönig kann immer noch durch seine Geißeldiener \"sehen\".\n\nAus diesem Grund seid Ihr hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12893] = { id = 12893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Euren Geist", description = "Ekel, Lady Nachtwald und der Springer würden im Kampf gegen den Lichkönig exzellente Waffen abgeben, wenn sie von seinem Willen befreit werden könnten. Genau das ist der Zweck des Herrschaftsstabs.\n\nIhr findet sie auf den Hängen im Osten und Westen des Gewölbes sowie auf der mittleren Ebene des Gewölbes über uns. Der Stab muss auf die drei Leichen angewandt werden.\n\nFliegt nun. Wir werden sie auf unsere Seite holen!", sourceObjective = "Baron Splitter im Schattengewölbe möchte, dass Ihr den Herrschaftsstab auf die Leichen von Ekel, Lady Nachtwald und dem Springer anwendet.", completion = "Wir werden diese drei gut gebrauchen können, wenn wir endlich das Gewölbe einnehmen.\n\nWo wir gerade dabei sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[12894] = { id = 12894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager der Kreuzfahrer", description = "Kreuzfahrer Dargath, Kreuzfahrer MacKellar, Ingenieur Schilf und die Zwillinge Gerk und Burr wurden vor Tagen zum Todesfeld entsandt, um dort eine neue Front zu eröffnen. Dem letzten Briefwechsel zufolge, hatten sie an der Grenze zu den Todesfeldern nordwestlich von hier erfolgreich ein Lager errichtet.\n\nAngesichts dieser neuen Informationen über Drakuru und Prinz Navarius denke ich, dass es nur klug wäre, jemanden schnellstens zum Lager der Kreuzfahrer zu entsenden.\n\nPackt Eure Sachen, {name}. Ihr müsst sofort los!", sourceObjective = "Sucht Kreuzfahrer MacKellar im Lager der Kreuzfahrer in Zul'Drak auf.", completion = "Es lief alles gut, bis die Geißel angriff. Sie haben sich mit Dargath, Gerk und Burr davongemacht und haben darüber hinaus auch unser Beförderungsmittel zerstört. Ratet mal, wer den Angriff angeführt hat.\n\n<MacKellar nickt.>\n\nNavarius...\n\nScheint, als wäre die ganze Gegend hier eine Art Werkstatt, in der Diener der Geißel hergestellt werden. Wir stehen mitten in einem verdammten untoten Minenfeld!", sourceObjectiveStatus = "unverified-source-field" }
quests[12895] = { id = 12895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Bronzebart", description = "Vor unserem Aufbruch erhielt ich die Akte, die Späher Vor'takh über diesen Brann Bronzebart angelegt hat. Seinen Tagebucheintragungen und Funden an den Grizzlyhügeln zufolge besteht kein Zweifel, dass Brann zu den Sturmgipfeln aufgebrochen ist. Bevor wir abstürzten sah ich noch kurz eine Lagerstätte. Sie liegt südlich von hier, jenseits der Fußmarschen, oberhalb des gefrorenen Flusses namens Bors Atemstrom. \n\nWenn Brann nicht dort ist, dann durchsucht das Lager und die Umgebung nach Hinweisen darauf, wohin dieser verflixte Zwerg aufgebrochen ist. Bringt mir alles, was Ihr dort findet.", sourceObjective = "Holt die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Boktar Blutfurie an der Absturzstelle Grom'ash.", progress = "Habt Ihr Bronzebarts Lager schon finden können?", completion = "Bei unserem Glück hätte ich das vermutlich vorhersehen müssen. Aber so leicht wird er mir nicht davonkommen. Ich bin gespannt, was in der Nachricht steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12896] = { id = 12896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man ihn nicht überzeugen kann", description = "Todesritter wie General Lichtbann werden an der kurzen Leine gehalten und können nur unter höchst außergewöhnlichen Umständen dazu gebracht werden, sich gegen den Lichkönig zu stellen.\n\nDer General hält sich ausschließlich im Gewölbe auf und überwacht die Erschaffung neuer Waffen. Wagt Euch an eines seiner Waffenregale in der Nordschmiede und er wird auftauchen, das versichere ich Euch. Ich werde Euch Ekel, Lady Nachtwald und den Springer zur Unterstützung schicken.\n\nWenn wir das Schattengewölbe endlich erobern wollen, muss General Lichtbann fallen!", sourceObjective = "Besiegt General Lichtbann und informiert anschließend Thassarian an Bord der Himmelsbrecher über Euren Erfolg.", completion = "General Lichtbann und seine Streitkräfte wurde besiegt? Das Schattengewölbe ist erobert?", sourceObjectiveStatus = "unverified-source-field" }
quests[12897] = { id = 12897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man ihn nicht überzeugen kann...", description = "Todesritter wie General Lichtbann werden an einer zu kurzen Leine gehalten, als dass wir sie vom Willen des Lichkönigs loslösen könnten... außer unter außergewöhnlichen Umständen.\n\nDer General hält sich innerhalb des Gewölbes auf und beaufsichtigt die Herstellung neuer Waffen. Sabotiert eines seiner Waffenregale an der nördlichen Schmiede und ich versichere Euch, er wird kommen. Ich werde Ekel, Lady Nachtwald und den Springer zu Eurer Unterstützung mitschicken.\n\nWenn wir das Schattengewölbe jemals erobern wollen, muss General Lichtbann fallen!", sourceObjective = "Besiegt General Lichtbann und berichtet dann Koltira Todesweber an Bord des Kanonenboots Orgrims Hammer von Eurem Erfolg.", completion = "General Lichtbann und seine Streitkräfte sind besiegt? Ist das Schattengewölbe eingenommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12898] = { id = 12898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengewölbe", description = "Das klingt, als hättet Ihr Euch außerordentlich gut geschlagen. Außerdem konntet Ihr dabei drei wichtige Verbündete für die Ritter der Schwarzen Klinge gewinnen.\n\n<Thassarian lässt seinen Blick zum Horizont schweifen.>\n\nIhr solltet zurückgehen. Inzwischen werden Baron Splitter und die anderen Todesritter erbittert kämpfen, um das Schattengewölbe gegen die Macht der Geißel zu verteidigen.\n\nSie werden gewiss Eure Hilfe benötigen.", sourceObjective = "Meldet Euch bei Baron Splitter im Schattengewölbe.", completion = "Schön, dass Ihr zurück seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12899] = { id = 12899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengewölbe", description = "Anscheinend seid Ihr sehr erfolgreich gewesen. Zudem habt Ihr im gleichen Atemzug drei sehr wichtige Verbündete für die Ritter der Schwarzen Klinge gewonnen.\n\n<Koltira blickt hinab auf die Karte am Boden.>\n\nIhr solltet zurückgehen. Mittlerweile werden Baron Splitter und die anderen Todesritter bestimmt bis zum letzten Blutstropfen darum kämpfen, das Schattengwölbe gegen den Ansturm der Geißel zu verteidigen.\n\nIch bin mir sicher, dass sie Eure Hilfe gebrauchen könnten.", sourceObjective = "Meldet Euch bei Baron Splitter im Schattengewölbe zurück.", completion = "Gut, dass Ihr zurückgekehrt seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12900] = { id = 12900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschirr anfertigen", description = "Ihr wollt also reiten? Wenn Ihr es so weit geschafft habt, dann habt Ihr wohl auch einen Versuch bei den Hildarthings verdient.\n\nAber eins nach dem anderen. Zuerst müssen wir Euch ein Geschirr anfertigen.\n\nIn den Klippen im Süden streifen vereinzelte Yetigruppen herum. Ihre Haut ist zäh und hat genau die richtige Dicke. Bringt mir einige, dann können wir dafür sorgen, dass Ihr Euch auf den Weg des Bärenreiters begebt.", sourceObjective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr 3 Bälge von Eismähnenyetis besorgt.", progress = "Habt Ihr die Bälge schon gefunden? Die Yetis streifen in den Hügeln unter uns herum.", completion = "Die sollten genügen. Ich werde das Geschirr für Euch bald fertig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12901] = { id = 12901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus nichts etwas herstellen", description = "Prinz Navarius muss gestoppt werden. Wir können nicht zulassen, dass die Geißel diese Gegend weiterhin als Werkstatt zur Zombieherstellung verwendet. Wenn wir den Panzer zum Laufen bekommen, dann könnten wir womöglich eine Chance haben. Was ich jetzt brauche, sind Ersatzteile.\n\nNordwestlich von hier befindet sich eine Gegend namens Thryms Ende. Die Armeen der Geißel benutzen diese Gegend als eine Art Basis. Über dieser Basis verteilt sind die Trümmer, die sie bei ihrer Ankunft hinterlassen haben. Überall liegt vereinzelter Metallschrott der Geißel herum. Beschafft Euch das Zeug und ich werde versuchen, es sinnvoll einzusetzen.", sourceObjective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr 10 Stück Metallschrott der Geißel beschafft.", progress = "Ich weiß wirklich nicht, ob dieser Plan funktionieren wird, {name}. Bringt mir einfach den Metallschrott und ich werde tun, was ich kann.", completion = "Was ist das für ein Schrott! Ah, verdammt! Es ist zu nichts zu gebrauchen. Das Metall der Geißel ist also nicht die Lösung. Was machen wir nur?", sourceObjectiveStatus = "unverified-source-field" }
quests[12902] = { id = 12902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Antworten", description = "Diese armen Kreaturen sind die einzigen Überlebenden.\n\nLaut dem, was ihr Häuptling sagt, seien Drakkaritrolle und Zornklauen jahrtausendelang Verbündete gewesen. Sie hätten hier über Generationen hinweg neben den Trollen gelebt und den Wandel der Welt um sie herum nicht bemerkt. Für die Zornklauen ist ein Troll ein Troll, also kam der Trollangriff auf ihren Bau überraschend.\n\nWir benötigen ein paar Antworten, {name}. Durchkämmt ihr Dorf südöstlich von hier nach Hinweisen darüber, wer oder was für diese Angriffe verantwortlich ist.", sourceObjective = "Durchsucht den Zornklauenbau nach Hinweisen darüber, wer oder was die Angriffe gegen die Wolvar der Zornklauen eingeleitet hat.", completion = "Da schwebt eine Schriftrolle über dem seltsamen Altar. Das muss genau das sein, wonach Kreuzfahrerlord Lantinga sucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12903] = { id = 12903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafür sind Freunde da...", description = "Wir wurden von Prinz Navarius und mindestens einem Dutzend Diener der Geißel angegriffen. Ich sagte zu Dargath und den Zwillingen, dass sie im Panzer bleiben sollen, doch sie wollten nicht auf mich hören. Dargath sah mir in die Augen und sagte: \"Wenn niemand diesen Panzer verlässt, dann werden sie uns alle umbringen.\" Anschließend ließ er Schilf den Motor abstellen und griff an. Das Heldenhafteste, was ich jemals gesehen habe.\n\nIch hörte, wie der Prinz den Monstern Befehle zubrüllte. Hat sich angehört, als würde er sie in nordwestliche Richtung nach Thryms Ende schicken. Wir müssen unsere Freunde retten. Werdet Ihr nach ihnen suchen?", sourceObjective = "Kreuzfahrer MacKellar im Lager der Kreuzfahrer möchte, dass Ihr nach Kreuzfahrer Dargath, Gerk und Burr sucht.", completion = "Die drei haben ein großes Opfer gebracht, das man so bald nicht vergessen wird. Ihr Dahinscheiden wird nicht umsonst gewesen sein. Wir werden siegreich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[12904] = { id = 12904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht verwehrt mir meine Rache", description = "Sie... sie haben meinen Bruder getötet.\n\n<Gerk kämpft gegen die Tränen an.>\n\nHaben ihn wie ein Tier abgeschlachtet. Nun liegt er auf einem ihrer Tische auf der anderen Seite des Lagers - bereit für ihre grauenhaften Experimente. Dargath ist auch tot. Der Paladin hat bei den Ruinen gen Nordosten eine echte Heldentat vollbracht, doch der Anführer der Vargul, Algar, war zu stark.\n\nIch bin als einziger übrig und werde auch bald tot sein. Ich... ich verwandle mich.\n\nWenn mir das Licht meine Rache verwehrt, werdet Ihr, {class}, sie mir dann gewähren? Tötet sie alle.", sourceObjective = "Gerk in Thryms Ende in Zul'Drak möchte, dass Ihr 15 Vargul tötet.", progress = "Ihr tut der Welt einen Gefallen, {class}. Diese Monster müssen aufgehalten werden!", completion = "<Gerk liegt im Sterben.>\n\nS... Sie sagen, dass diese Vargul... diejenigen sind... die der Lichkönig als unwürdig erachtete. Kön... könnt Ihr Euch... das vorstellen? Den... Denkt nur einmal daran... wie mächtig... diejenigen sein müssen, die... würdig sind...\n\nIch werde für Euch beten, Held... im Jenseits... Möget Ihr nie mehreren von ihnen begegnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12905] = { id = 12905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mildred die Grausame", description = "Abgemacht, {name}. Ihr helft mir, mich von diesen Ketten zu befreien, und ich helfe Euch, Euren kleinen grünen Freund zu finden.\n\nDie Hyldnir, die diese Mine leitet, wird Mildred die Grausame genannt und das aus gutem Grund.\n\nSagt ihr, dass Ihr geschickt wurdet, um bei der Arbeit in den Minen zu helfen. Tut, was auch immer sie von Euch verlangt, bis sie Euch die Schlüssel für meine Ketten anvertraut.", sourceObjective = "Sprecht mit Mildred der Grausamen in der verlassenen Mine.", completion = "Ich habe auf Ersatz für einen meiner Aufseher gewartet. Wurde langsam Zeit, dass du auftauchst.\n\nNa, dann schicken wir dich mal an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12906] = { id = 12906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin", description = "Dann wollen wir dir für den Anfang mal etwas Leichtes geben. Die Vrykulmänner, die für uns in den Minen schuften, tun dies gegen ihren Willen... und lediglich aus Furcht vor unseren Klingen.\n\nHin und wieder verliert einer von ihnen seine Motivation. Haltet nach denjenigen Ausschau, die nicht kooperieren wollen, und weist sie in ihre Schranken.\n\nHier, nimm diese Disziplinarrute - du willst Schmerzen zufügen und niemanden totschlagen. Nun ja, die meiste Zeit zumindest.", sourceObjective = "Mildred die Grausame an der verlassenen Mine möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul anwendet.", progress = "Bist du fertig? Hoffe, du hast nicht zu viele von diesen Mistkerlen totgeschlagen. Wir brauchen die Arbeitskräfte.", completion = "Für eine neue Aufseherin nicht schlecht. Ich hab' noch eine andere Aufgabe, falls du dich heute mutig fühlst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12907] = { id = 12907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exempel statuieren", description = "Auf jede Aktion folgt eine Gegenreaktion, Schwester. In unserem Fall sieht es wie folgt aus: Wir üben Druck auf die Männer aus und als Folge wurden neue Gerüchte über einen Aufstand laut.\n\nDas bärtige Schwein hinter diesen Hetzreden wird Garhal genannt. Schafft ihn beiseite... und sorgt dafür, dass die anderen Männer sein Ableben mitverfolgen. Sie müssen lernen, dass Ungehorsam nicht toleriert wird.", sourceObjective = "Mildred die Grausame in der verlassenen Mine möchte, dass Ihr Garhal tötet.", completion = "Wenn ich am Anfang Bedenken bezüglich Eures Engagements hatte, dann sind diese nunmehr verflogen. Noch ein klein wenig mehr Mühe von Eurer Seite her und Ihr könntet zu einem permanenten Mitglied meiner Operation werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12908] = { id = 12908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bestimmte Gefangene", description = "Ihr seid gnadenlos und habt Euch in dieser Gegend bewährt.\n\nIch habe eine weitere Aufgabe für Euch. Eine der gefangenen Vrykul ist zu einer größeren Belastung geworden, als vorauszusehen war.\n\nSie besaß die Frechheit, auf ihr Recht zu pochen, am Hildarthing, unserem heiligen Wettstreit der Stärke und Kampfkünste, teilnehmen zu dürfen.\n\nHier ist der Schlüssel zu ihren Fesseln. Aber macht es so schmerzlos wie möglich, denn sie ist immerhin eine Frau, wenn auch keine von uns.", sourceObjective = "Bringt Mildreds Schlüssel zu Lok'lira der Greisin in die verlassene Mine.", progress = "Wurde auch langsam Zeit.", completion = "Ich wusste, dass Ihr zurückkommt! Befreit mich von diesen Fesseln, dann helfe ich Euch, den Goblin zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12909] = { id = 12909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nase trauen", description = "Um Brann aufzuspüren, brauchen wir eine Kreatur mit präzisem Geruchssinn, die gut Spuren lesen kann. Zwar waren im Zeppelin keine Hunde, aber ich glaube, ich habe einen Ersatz gefunden.\n\nNach dem Absturz schickte ich Khaliisi den Osthang des Berges hinab, um zu jagen. Ihre Katze Frostbeißer kann im Schnee hervorragend Beute machen. Sagt ihr, dass sie sich vorerst von ihrer Gefährtin trennen muss. Sie kann allein jagen, aber wir haben keine andere Möglichkeit, Brann Bronzebart zu finden.", sourceObjective = "Sprecht mit Khaliisi am Fuße des Berges östlich der Absturzstelle Grom'ash.", completion = "Boktar hat Frostbeißer also eine andere Aufgabe zugedacht, was? Nun, ich hoffe wirklich für ihn, dass die Sache wichtig ist. Er weiß, dass man einen Jäger normalerweise nicht von seinem Gefährten trennt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12910] = { id = 12910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Täter ausschnüffeln", description = "Dieses Mal werde ich Boktar seinen Willen lassen, doch ich erwarte von ihm, dass er es auch wieder gut macht. Seht mich nicht so an. Boktar mag vielleicht das Kommando haben, doch niemand sagt einem Jäger, was er zu tun hat.\n\n'Dein Begleiter muss verschwinden,' sagt er. 'Mach, dass er zu Knurren aufhört.'\n\nUnd ganz plötzlich ändert er seine Meinung, so wie es ihm gerade in den Kram passt. Dann wieder beschwert er sich darüber, dass Frostbeißer ihn ein wenig gebissen haben soll. Doch keine Sorge, er wird Euch ausgezeichnete Dienste leisten und Eure Beute aufspüren. Nachdem er sein Ziel gefunden hat, liegt es an Euch, mit den Eisenzwergen, Brann oder wen auch immer Ihr finden mögt fertig zu werden.", sourceObjective = "Schwingt Euch auf Frostbeißer und folgt der Fährte von Branns Notiz bis zu ihrem Ausgangspunkt. Beschafft anschließend Branns Kommunikator und stellt mit seiner Hilfe Kontakt mit Brann Bronzebart her.", progress = "Wer... wer seid Ihr?", completion = "<Ihr aktiviert den Kommunikator und das Bild eines Zwergen erscheint. Es kann sich nur um Brann Bronzebart handeln.>\n\n<Seinem Gesichtsausdruck nach zu urteilen, scheint Brann erschrocken darüber zu sein, Euch zu sehen, und fängt an, wie wild zu gestikulieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test" }
quests[12912] = { id = 12912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Sturm rückt an", description = "Ihr seid nicht wie die anderen, <mein Kleiner/meine Kleine>. Ihr stinkt nicht nach uraltem Tod. Womöglich kann man Euch vertrauen.\n\nIch bin Gymer, König der Sturmriesen. Ich wurde von meinem Bruder Thiassi, jetzt ein untoter Diener des Lichkönigs, hierher gelockt. Als ich erkannte, dass sein Hilferuf eine Falle ist, war es schon zu spät. Nun bin ich ein Gefangener der Geißel und ich fürchte, dass ich schon bald dasselbe Schicksal teilen werde, wie viele andere Sturmriesen.\n\nFindet einen Weg, mich aus diesem Käfig zu befreien, und ich werde Euch helfen, so gut ich kann.", sourceObjective = "Gymer, König der Sturmriesen, hat Euch gebeten, einen Weg zu finden, ihn aus seinem Käfig zu befreien. Sprecht mit Ingenieur Schilf im Lager der Kreuzfahrer.", completion = "Ein... ein Sturmriese? Ich weiß nicht so recht, {name}. Das hört sich riskant an. Auf der anderen Seite denke ich nicht, dass wir allzu viele Möglichkeiten haben.\n\nWenn ich das mache, dann müsst Ihr mir versprechen, dass Ihr Euren Freund dazu bringt, uns dabei zu helfen, mit Navarius und seinen Spießgesellen fertig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12913] = { id = 12913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprich Orcisch, Mann!", description = "<Brann fängt an, wie wild zu gestikulieren und in seiner Muttersprache zu faseln.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\nGar Ruk dagUm loch angor-magi ta har ruk!\n\n<Ein wenig später erkennt Ihr, dass das Gespräch zu nichts führt. Vielleicht wird der Schamane Moteha Windkind bei der Absturzstelle Grom'ash wissen, was zu tun ist.>", sourceObjective = "Sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", completion = "Boktar wird nicht erfreut darüber sein, dass Ihr Brann nicht gefunden habt, doch zumindest seid Ihr nicht mit leeren Händen zurückgekehrt. Nun lasst uns sehen, was wir wegen diesem plappernden Zwerg machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12914] = { id = 12914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gymers Rettung", description = "Ihr meint also, dass er in einen 30 Meter großen Käfig gesperrt ist, wie?\n\nWenn meine Berechnungen stimmen, dann sollten wir zumindest die Scharniere des Käfigs schwächen können, um dem Riesen genug Spielraum zum Ausbrechen zu geben.\n\nDamit das funktioniert, brauche ich ein paar Verflüssiger und Stabilisatoren.\n\nDie Essenz der Banshees sollte sich sehr gut als Verflüssiger eignen. Ihr könnt das Zeug von den Banshees in den toten Feldern nordöstlich von hier bekommen. Die Stabilisatoren könnt Ihr von den Erdwütern im Südwesten nahe der Schwarzen Wacht bekommen.\n\nBewegt Euch!", sourceObjective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr ihm 6 Essenzen der Banshees und 6 Einheiten Kieselerde bringt.", progress = "Ohne die Verflüssiger und Stabilisatoren werde ich nie den Sprengstoff herstellen können, den wir benötigen, um Euren Freund aus seinem Gefängnis zu befreien.", completion = "Glücklicherweise haben wir genug Sprengstoff gehabt. Die riesige Zephyriumladung herzustellen, sollte dank der Materialien, die Ihr mir gebracht habt, kein Problem mehr darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12915] = { id = 12915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zäune reparieren", description = "Wenn ich den Tempel der Schöpfer aus meines Bruders Kontrolle entreißen möchte, müssen die Dinge zwischen mir und meinen alten Verbündeten besser stehen.\n\nVielleicht wäre es ein erster Schritt zu einer neuen Freundschaft mit den Frostriesen, wenn wir zusammen einen gemeinsamen Feind vernichten würden.\n\nFjorn hat zur Belagerung von Dun Niffelem Eisenriesen eingesetzt. Er befindet sich bei Fjorns Amboss weit östlich von hier - geht dorthin und besiegt ihn. Schwächt seine Streitkräfte so weit, bis die Söhne Hodirs den Sieg davontragen.\n\nHier, {name}, nehmt diesen Glücksbringer und ruft mit ihm meine Irdenen zu Hilfe.", sourceObjective = "Thorim im Tempel der Stürme möchte, dass Ihr Fjorn und 5 Sturmgeschmiedete Eisenriesen in Fjorns Amboss östlich von Dun Niffelem tötet.\n\nMit Thorims Glücksbringer der Erde könnt Ihr seine Irdenen zur Unterstützung holen. Zum Benutzen des Glücksbringers benötigt Ihr einen Granitfelsen aus Fjorns Amboss in der Nähe.", completion = "Es ist also vollbracht.\n\nHoffen wir, dass es ausreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12916] = { id = 12916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere einzige Hoffnung", description = "Das, was ich Euch gleich geben werde, nennt sich Zephyrium. Die Substanz ist hochexplosiv und weist einige besondere Eigenschaften auf. Dank seiner Formbarkeit, werdet Ihr die Scharniere und Spalten füllen können und so maximalen Schaden anrichten.\n\nKehrt zu Eurem Freund zurück und benutzt die riesige Zephyriumladung, um ihn zu befreien.\n\nHoffen wir, dass er seinen Teil der Abmachung einhalten wird. Er ist unsere einzige Hoffnung.", sourceObjective = "Sprecht mit Gymer in Thryms Ende in Zul'Drak, nachdem Ihr mit der riesigen Zephyriumladung die Umzäunung der Geißel geöffnet habt, in welcher der Gefangene festgehalten wird.", progress = "Ich bin ein Riese meines Wortes, mein Kleiner.", completion = "FREIHEIT!\n\nHabt keine Angst, mein Kleiner. Gymer ist ein ehrenhafter Riese. Ich wünsche genauso wie Ihr und Euer Volk, dass die Geißel aus diesem Land vertrieben und der Lichkönig vernichtet wird. Ich werde Euch wie versprochen so gut wie möglich helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12917] = { id = 12917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Stimme des Windes sprechen", description = "Ich denke, mit unserem Glück hätten wir nicht erwarten sollen, Brann so leicht zu finden. Wenn wir herausfinden können, was Brann sagt, könnt Ihr ihn davon überzeugen, seinen Ort preiszugeben.\n\nDie Macht des Windes ist in diesen Bergen stark, was sich uns als äußerst nützlich erweisen könnte. Ein geübter Schamane kann den Klang aller Stimmen dieser Welt über den Wind hören.\n\nIm Nordwesten, auf der verschneiten Ebene, werdet Ihr Kreaturen des Windes finden, die Sturmreiter. Fangt ihre Stimmen ein und bringt sie zu mir.", sourceObjective = "Bringt 5 Stimmen des Windes zu Moteha Windkind an der Absturzstelle Grom'ash.", progress = "Habt Ihr die Stimmen des Windes?", completion = "Ihr solltet jetzt mit dem Zwerg sprechen können. Fragt Boktar, was er von Euch benötigt. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12918] = { id = 12918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine perfektionieren", description = "Ist so kalt wie der Atem eines Frostwyrms hier oben, findet Ihr nicht? Mir fehlen nicht nur die Kunden für mein Handwerk, sondern auch der Vorrat an Edelsteinen, die ich verkaufen könnte. Wenn Ihr mir einige ungeschliffene Edelsteine für meine Vorräte bringen würdet, dann könnte ich Euch beibringen, wie man Edelsteine perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", sourceObjective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Ounhulo in Valgarde.", progress = "Ihr seid zu großzügig. Das Mindeste, was ich tun kann, ist, Euch beizubringen, wie man einen Edelstein perfektioniert.", completion = "Das sind die perfekten Exemplare für meine Vorräte. Ich werde Euch nicht nur beibringen, wie man das Handwerk des Edelsteinschleifens perfektioniert, nein, ich werde außerdem einen der Edelsteine in seine perfekte Form schleifen und ihn Euch dann als Belohnung geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12919] = { id = 12919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Sturmkönigs", description = "Der Lichkönig hat mein Volk dezimiert. Nun verwendet die Geißel die Leichen von Sturmriesen, um daraus entweder hirnlose Fleischriesen zu erschaffen oder noch Schlimmeres: zusammengeflickte Monstrositäten wie Thrym.\n\nIch werde vor nichts zurückschrecken, um dafür zu sorgen, dass sie alle von dieser Welt getilgt werden. Zusammen werden wir die Diener der Geißel vernichten, die Zul'Drak bedrohen.\n\nWir werden sie alle töten: Navarius, Algar und Thrym!\n\nWenn Ihr bereit seid, dann lasst es mich wissen und wir werden unsere Zerstörungsreise antreten.", sourceObjective = "Sprecht mit Gymer, um auf ihm zu reiten.\n\nVernichtet 100 Diener der Geißel und Algar den Auserwählten, Thrym und Prinz Navarius. Meldet Euch bei Kreuzfahrer MacKellar im Lager der Kreuzfahrer, falls Ihr erfolgreich sein solltet.", completion = "Unglaublich! Darüber wird man noch lange, lange Zeit reden, {name}! Ein Mann ritt auf dem Kopf des Königs der Sturmriesen und vernichtete eine ganze Armee der Geißel!\n\nUnd ich war da, als es passierte...", sourceObjectiveStatus = "unverified-source-field" }
quests[12920] = { id = 12920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brann einholen", description = "Worauf wartet Ihr noch? Dank Moteha wurde die Sprachbarriere durchbrochen. Tretet mit Brann Bronzebart in Verbindung und versucht, so viel wie möglich darüber herauszufinden, wo er sich versteckt hält und hinter was er her ist.\n\nVielleicht lässt sich aus diesem Desaster noch etwas Gutes gewinnen.", sourceObjective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen. Erstattet anschließend Boktar Blutfurie bei der Absturzstelle Grom'ash Bericht.\n\nFalls Ihr Branns Kommunikator verlieren solltet, dann sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", progress = "Was habt Ihr herausgefunden?", completion = "<Boktar lauscht Eurem Bericht über Euer Gespräch mit Brann.>\n\nAn den Worten des Zwergs ist etwas Wahres dran. Vor'takhs Plan ist nicht der Stil der Horde. Wenn Brann Bronzebart einen Weg kennt, wie diese Eisenzwerge und ihre Schutzherren aufzuhalten sind, dann dient es unserer Sache, ihm zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12921] = { id = 12921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapetenwechsel", description = "Ausgezeichnet. Am östlichen Ende der Mine gibt es einen Ausgang, der nach Brunnhildar führt. Macht Euch auf den Weg dorthin. Ich werde Euch dort treffen.\n\nWir dürfen nicht gemeinsam gesehen werden, damit nicht der Verdacht entsteht, dass Ihr mir helft. Ich werde meine Magie dazu verwenden, mein Aussehen zu verändern. Macht Euch keine Sorgen, {race}. Wir werden Euren Freund im Nu gefunden haben.", sourceObjective = "Trefft Euch mit Lok'lira der Greisin in Brunnhildar.", completion = "Ihr seid hier - gut. Ich denke, dass ich jetzt weiß, wo sich Euer Goblin befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12922] = { id = 12922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Veredlers Feuer", description = "Ein geheimnisvolles Schimmern tritt durch die poröse Außenfläche dieses Stück Metalls nach Außen.\n\nIhr habt das Gefühl, dass es das Klügste wäre, die Schlacke mit Fjorns Amboss wegzubrennen.\n\nWährend Ihr gerade darüber nachdenkt, wo Ihr in dieser gefrorenen Einöde etwas finden könntet, das heiß genug dafür wäre, läuft Euch ein Feuerklagegeist über den Weg...", sourceObjective = "Ihr müsst 10 wütende Funken von den wutentbrannten Klagegeistern auf dem Frostfeldsee sammeln und anschließend den Amboss bei Fjorns Amboss verwenden.", progress = "Die Oberfläche des Ambosses ist glühend heiß, im scharfen Gegensatz zu der winterlichen Luft, die ihn umgibt.", completion = "Ihr legt das Metall auf den Amboss und sofort, nachdem Ihr die Funken dazugegeben habt, fangen sie an, das Erz wie wild zu bearbeiten.\n\nAls die Funken schließlich verglüht sind, ist nur noch ein großes Stück Metall übrig, das auf besondere Art und Weise schimmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12924] = { id = 12924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündnis schließen", description = "<Thorim lächelt zum ersten Mal, seitdem Ihr ihn kennt.>\n\nLangsam fängt es an, so auszusehen, als hätte das Schicksal seine Finger im Spiel, {race}.\n\nEure Entdeckung stellt die Überbleibsel meiner Rüstung dar, die ich vor langer Zeit in einem Anflug von Trauer abgeworfen und den Elementen überlassen habe. Nur die Söhne Hodirs können sie neu schmieden - sie sind die eigentlichen Erbauer.\n\nWomöglich habt Ihr genug getan, um ihren Hass mir gegenüber zu beschwichtigen. Sucht ihren König Jokkum auf, falls er noch lebt.\n\nVersucht, seine Gunst zu gewinnen, und erbittet seine Hilfe.", sourceObjective = "Ihr sollt nach Dun Niffelem gehen und König Jokkum darum bitten, Thorims Rüstung neu schmieden zu lassen. Nachdem Ihr Jokkums Aufgabe abgeschlossen habt, sollt Ihr mit Njormeld in Dun Niffelem sprechen.", completion = "Es scheint, als wäre meine Technik erheblich besser geworden. Entweder ist es das oder die Legenden, die diesen Amboss umranken, sind wahr.\n\nDiese Rüstung ist besser als die alte und hat weniger Materialien benötigt.\n\nMit dem, was übrig geblieben ist, konnte ich etwas für Euch anfertigen - als Bezahlung für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12925] = { id = 12925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missgeburten", description = "Der Lichkönig hat uns zu drei verschiedenen Gelegenheiten Botschafter geschickt. Alle drei wurden auf der Stelle vernichtet.\n\nUnsere Schwestern in Valkyrion waren unseren Traditionen nicht so treu und gingen auf die Annäherungsversuche der Geißel ein. Anstatt die wilden Drachen zu fangen, lassen sie sie nun aus der Verseuchung und dem Schmutz auferstehen, in dem sich die Geißel suhlt.\n\nNehmt das Frostöl, das die Valkyrion von Hyldnir bei sich tragen, und lasst damit alle Eier, die Ihr findet, gefrieren. Gerüchten zufolge gibt es dort, wo die Eier aufbewahrt werden, auch einen verrotteten Tümpel der Verseuchung.", sourceObjective = "Thyra Kvinnshal in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", completion = "Wir sind Euch sehr dankbar, Schwester, denn wir können nicht zulassen, dass mit unseren wichtigen Traditionen gebrochen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12926] = { id = 12926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile des Rätsels", description = "Wir konnten mitverfolgen, wie die Eisenzwerge und ihre Konstrukte die Steinwesen, die Brann die Irdenen nennt, gemeinsam mit ihren verbündeten Riesen angriffen. Tretet mit ihm in Verbindung und helft ihm so gut Ihr nur könnt und vergesst nicht, dass alles, was Ihr von ihm und seiner Suche erfahren könnt, uns bei unserem Kampf gegen die Eisenzwerge und ihren Meister eine Hilfe sein könnte.", sourceObjective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen.", progress = "Habt Ihr die Scheibe zusammengefügt?", completion = "Das ging aber schnell! Nun, da wir die Scheibe haben, müssen wir herausfinden, wie wir zur ersten Hälfte des Archivschlüssels gelangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12927] = { id = 12927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daten schürfen", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Bewahrer Mimir, der Tüftler, der diese Bibliothek errichtet hat, muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um; sind dort irgendwelche Datenbanken?\n\nVielleicht ist das der Zweck dieser Scheibe. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", sourceObjective = "Nutzt die Scheibe des Erfinders, um 7 versteckte Daten aus den Datenbanken zu beschaffen.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "<Brann sieht die Scheibe in Eurer Hand an.>\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n<Ihr beschreibt den Datenbeschaffungsprozess.>\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12928] = { id = 12928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannons Schale", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", sourceObjective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", progress = "Habt Ihr Norgannons Schale gefunden?", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, {name}. Archäologe Andorin hat schon sehr lange nach Hinweisen darauf gesucht, wo diese Schale zu finden ist. Er wird mir nie glauben, dass stattdessen ein mutiger {race} sie gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12929] = { id = 12929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Irdenen von Ulduar", description = "Die Irdenen, die einst Ulduar bauten, bewohnten und verwalteten, wurden aus ihrem Zuhause vertrieben, als Loken die Stadt einnahm. Seitdem wurden die Verbannten von den Eisenzwergen ununterbrochen angegriffen.\n\nSie haben in einem alten Gebäude der Titanen an der Bergwand westlich der Bibliothek des Erfinders Zuflucht gefunden und ihm den Namen \"Bergfels' Zuflucht\" gegeben. Bergfels und seine Brüder kämpfen dagegen an, dass die Eisenzwerge ihren Zufluchtsort überrennen, doch sie können nicht mehr lange standhalten. Findet sie und helft ihnen, {name}.", sourceObjective = "Sprecht mit Bergfels dem Steinformer in Bergfels’ Zuflucht.", completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf mit Loken und seinen Anhängern, im Kampf um Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12930] = { id = 12930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Erde", description = "Es scheint schon so lange her zu sein, dass diese Hämmer Stein anstatt Eisen schlugen. Als wir aus Ulduar vertrieben wurden, mussten die schwächsten von uns sterben - die stärksten unserer Handwerker wurden zu Kriegern.\n\nDoch als die Eisenzwerge uns zurückschlugen, mussten selbst die Stärksten ihre Niederlage eingestehen.\n\nWir können nur wenig für die Verwundeten tun, außer uns stünde ein Vorrat an verzauberter Erde zur Verfügung. Einst bauten wir die Vorkommen an den steilen Klippen gen Nordwesten ab, aber der ständige Kampf hat uns davon abgehalten, unsere Vorräte wieder aufzufüllen. Würdet Ihr bitte helfen?", sourceObjective = "Baut mit der Spitzhacke der Irdenen 7 Klumpen verzauberte Erde ab. Bringt anschließend die Erde und 5 Einheiten Froststoff zu Bergfels dem Steinformer in Bergfels' Zuflucht.", progress = "Habt Ihr ein bisschen Erde finden können?", completion = "Das wird uns erlauben, noch mehr der Gefallenen zusammenzuflicken. Im Namen aller Verteidiger der Zuflucht möchte ich Euch danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12931] = { id = 12931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Die Verteidiger der Zuflucht haben ihr Bestes gegeben, um die Angriffe der Eisenzwerge abzuschwächen, doch wir müssen weiterhin Stück für Stück vor ihnen zurückweichen. Meine Männer sind zäh, aber nicht unermüdlich. Ohne Verstärkung ist es nur eine Frage der Zeit, bis wir überrannt werden.\n\nWürdet Ihr uns mit Eurem Können bei der Verteidigung der Zuflucht zur Seite stehen? Die Moral der Verteidiger würde dadurch erheblich gesteigert werden und ihnen, wie auch mir, Hoffnung auf einen Gegenschlag geben.\n\nTötet jeden der Sturmgeschmiedeten, der Euch außerhalb der Zuflucht über den Weg laufen sollte. Vernichtet auch ihre Kreationen.", sourceObjective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 10 sturmgeschmiedete Angreifer tötet und anschließend zu ihm zurückkehrt. Ihr könnt entweder sturmgeschmiedete Räuber oder Häscher töten.", completion = "Ihr habt den Verteidigern etwas gegeben, über das sie sich freuen können. Zu sehen, wie der Feind durch Eure Hand fällt, hat ihnen neue Kraft verliehen und ihren Mut gestärkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12932] = { id = 12932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Yggdras!", description = "Ich sag Euch mal was, <Freundchen/meine Gute>, zwischen diesem Ort hier und den rollenden Ebenen von Nagrand ist ein großer Unterschied. Die Trolle hier sind zwar dreckiger als Oger - aber sein wir doch mal ehrlich: Ich geh' dorthin, wo es Gold gibt! Seid also willkommen in Zul'Drak, <Kollege/Kollegin>.\n\nIhr macht das erste Mal bei diesem Spektakel mit - na dann lasst mich Euch erstmal erzählen, was Sache ist. Ich bin der Kampfveranstalter und dieser quirlige Troll neben mir ist Wodin mein Leibwächter. Ihr seid die Unterhaltung. Wenn Ihr kämpfen wollt, dann sagt mir Bescheid und ich werde einen Kampf für Euch organisieren.\n\nWenn Ihr bereit seid und eine Gruppe Leute mitgebracht habt, dann können wir anfangen! Was meint Ihr dazu?", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Nicht schlecht, Herr Specht. Ihr könntet hier sogar ein wenig Gold machen - falls Ihr am Leben bleiben solltet, natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12933] = { id = 12933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Magnataur!", description = "Der nächste Kampf ist erste Sahne, <mein Freund/meine Gute>! Anscheinend will so ein Magnataur aus der Drachenöde ein Stück vom Kuchen abbekommen. Habt Ihr schon mal gegen einen von denen gekämpft? Alles, was ich Euch sagen kann, ist, hoch zu zielen!\n\nGebt mir ein Zeichen und wir bringen die Party ins Rollen.", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Stinkbart! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Wow! Als ich Stinkbart zum ersten Mal gesehen hab, dachte ich, dass Ihr geliefert wärt! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12934] = { id = 12934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Aus einer anderen Welt!", description = "Ich werde Euch nicht belügen, <Kumpel/meine Dame>. Könnte sein, dass Ihr dem hier nicht gewachsen seid. Euer nächster Gegner kommt aus den Elementarebenen! Ich weiß nicht mal, was genau in der Arena auftauchen wird!\n\nHinein mit Euch, falls Ihr denkt, dass Ihr das schaffen könnt, und gebt ihnen Saures!", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt einen der Elementarfürsten! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Unglaublich! Als das Ding auftauchte, dachte ich zuerst, dass der ganze Laden hier in die Luft gehen würde! Ihr habt diese Runde wirklich dominiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[12935] = { id = 12935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Tuskarrmageddon!", description = "Euer nächster Gegner hat eine fiese, schaurige Art zu kämpfen, <Kleiner/Kleine> - die Art zu kämpfen, die man nur drauf haben kann, wenn man einmal die Radieschen von unten gesehen hat. Er ist kampfeshungrig und wird alle Register ziehen, um zu gewinnen. Passt auf! Ich habe gehört, dass er zur Übung mit Yetis kämpft!\n\nWir fangen an, wenn Ihr bereit seid.", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Orinoko Hauerbrecher! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Ich hab' mir schon ein wenig Sorgen gemacht, {name}. Als er die Seehunde und Pinguine auf Euch losgelassen hat... nun, da wusste ich nicht so recht, was ich davon halten sollte. Hat so ziemlich lächerlich ausgesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12936] = { id = 12936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Korrak der Blutrünstige!", description = "Ihr werdet das nicht glauben, {class}. Euer nächster Kampf wird gegen Korrak den Blutrünstigen sein! Sieht so aus, als würden die Drakkaritrolle die Muskeln spielen lassen! Und lasst es mich Euch sagen: Er hat vom Saft der Tiergötter genippt. Er ist gut und dazu bereit, Euch in den Boden zu stampfen.\n\nSeid Ihr bereit?", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Korrak den Blutrünstigen! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Verdammt, ich kenne Korrak noch von ganz früher, als ich noch jünger war und für den Frostwolfklan arbeitete. Er konnte nie die Klappe halten! Ich denke, dass Ihr der Welt gerade einen großen Gefallen getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12937] = { id = 12937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Gefallenen", description = "Die Verteidiger der Zuflucht kämpfen tapfer, aber sie sind dem eisernen Ansturm einfach nicht gewachsen.\n\nAus der von Euch gesammelten Erde kann ich Bandagen anfertigen, die helfen werden, die Wunden einiger Gefallener zu heilen. Je mehr Verteidiger wir zusammenflicken können, umso länger werden wir hier draußen durchhalten.\n\nHier, nehmt diese Packungen und wendet sie auf die Wunden der gefallenen Verteidiger außerhalb der Zuflucht an. Bringt so viele in die Schlacht zurück, wie Ihr nur könnt, {name}. Jeder Verlust ist ein Verlust zu viel.", sourceObjective = "Heilt mithilfe der Vulkanschlammpackung 8 gefallene Irdene Verteidiger und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", completion = "Die Krieger, die Ihr geheilt habt, werden helfen, die Linie noch länger zu halten. Wenn wir die Bedrohung durch die Eisernen wirklich loswerden wollen, dann müssen wir einen Weg finden, sie hinter den Linien anzugreifen", sourceObjectiveStatus = "unverified-source-field" }
quests[12938] = { id = 12938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herzog", description = "Wir brauchen Eure volle Konzentration, {name}. Wir können das Schattengewölbe zurzeit kaum halten. Wie Ihr sehen könnt, haben wir den Lichkönig erfolgreich geärgert.\n\n<Der Baron kichert.>\n\nIch möchte, dass Ihr mit Herzog Lankral sprecht. Er hat hier jetzt das Kommando. Ihr findet ihn innerhalb des Gewölbes.\n\nWenn ich Ihr wäre, würde ich ihn nicht warten lassen.", sourceObjective = "Sprecht mit Herzog Lankral im Schattengewölbe.", completion = "Ich freue mich, Euch endlich kennenzulernen, {name}. Wir schulden Euch viel, aber noch seid Ihr nicht fertig hier.\n\nEs gibt eine Vrykulstadt hinter den Bergen im Westen, die Jotunheim genannt wird.\n\nDie dortigen Vrykul stehen andauernd vor der Herausforderung 'aufzusteigen'. Die Gewinner gehen nach Ymirheim, um dem Lichkönig als dessen Elitekriegerkaste zu dienen, den Ymirjar, während die Verlierer zu Verseuchten Vargul reduziert werden.\n\nIhr werdet dafür sorgen, dass mehr Vargul als Ymirjar daraus hervorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12939] = { id = 12939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenhafte Herausforderung", description = "Der erste Schritt, den wir machen werden, findet an einem Ort in Jotunheim statt, den man Wilde Klippe nennt. Er liegt gleich hinter den Bergen im Westen.\n\nAuf der Klippe trainieren die Vrykul-Krieger und werden von den Männern ihres Thans in der hohen Kunst des Kampfes ausgebildet.\n\nIch möchte, dass Ihr diese Flagge nehmt und einige von ihnen herausfordert. Wir sollten sie mit 'simplen' Fähigkeiten demoralisieren, findet Ihr nicht, {race}?\n\n<Der Herzog grinst und seine verrotteten Zähne blitzen im trüben Licht des Gewölbes.>", sourceObjective = "Herzog Lankral vom Schattengewölbe bittet Euch, die Herausforderungsflagge zu nutzen und 6 Mjordinkrieger zu besiegen.", completion = "Ich habe bereits von Euren Fortschritten auf der Wilden Klippe gehört. Großartig, {name}... wirklich großartig!\n\n\n\nUnd nun ist es Zeit, einen Erlass an den Than aufzusetzen, dessen Vrykul Ihr derart leicht besiegen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12940] = { id = 12940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12941] = { id = 12941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12942] = { id = 12942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißt ihnen die schwarzen Schwingen aus", description = "Verräter. Wir Hyldnir können sie nicht leiden.\n\nDie Bewohner von Valkyrion sind schon viel zu lange ungeschoren davongekommen. Während wir Thorim treu geblieben sind, wurden sie zu Schoßhündchen des Lichkönigs!\n\nSie nennen diejenigen, die sein Geschenk empfangen haben, die Val'kyr. Sie fliegen mit gefiederten Flügeln, wie es Harpyien nun einmal so tun.\n\nIhr findet Valkyrion weit im Nordwesten hinter dem Tempel der Stürme. Erschlagt diese geflügelten Wölfinnen, Schwester. Erschlagt sie und ich werde Euch mit einem meiner wertvollsten Besitztümer belohnen.", sourceObjective = "Iva die Rachsüchtige in Brunnhildar möchte, dass Ihr nach Valkyrion geht und 12 werdende Val'kyr erschlagt.", completion = "Die Val'kyr sind lediglich die Schoßhündchen des Lichkönigs. Sie werden getötet werden, diese Miststücke. Sie haben ihre Wahl getroffen, nun müssen sie sich den Konsequenzen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12943] = { id = 12943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlass des Schattengewölbes", description = "Than Ufrang der Mächtige residiert in seiner Halle mit Blick über die Wilde Klippe. Ich habe ihn beobachtet. Der Than ist ein geduldiger Vrykul, der Sinn für Strategie und die Kriegsführung besitzt. Er hat außerdem eine Neigung dafür gezeigt, abzuwarten und es in der anhaltenden Schlacht nicht zu übertreiben.\n\nEr muss sterben!\n\nIch habe einen Erlass aufgesetzt. Stellt Euch vor den Than und lest ihn laut vor.\n\n<Der Herzog zieht amüsiert eine Augenbraue hoch.>\n\nDas sollte ihn... zumindest reizen.", sourceObjective = "Herzog Lankral vom Schattengewölbe hat angeordnet, dass Ihr den Erlass des Schattengewölbes laut vor Than Ufrang dem Mächtigen vorlest und ihn dann tötet.", completion = "<Herzog Lankral nickt zustimmend, als Ihr ihm von Eurem Erfolg berichtet.>\n\nWir haben es mit einem Gegner zu tun, der uns nicht nur körperlich, sondern auch zahlenmäßig zusetzt. Wenn wir den Kampf um Eiskrone gewinnen wollen, dann müssen wir ihn überlisten!\n\nUfrangs Tod verschafft uns in Jotunheim einen Vorteil. Sehen wir einmal, ob wir ihn nutzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12944] = { id = 12944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
