quests[13031] = { id = 13031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelswächter der Älteste", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13032] = { id = 13032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muraco der Älteste", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13033] = { id = 13033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arp der Älteste", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13034] = { id = 13034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeuge und der Held", description = "Als ich meine Reisen in Nordend angetreten hatte, besuchte ich die boreanische Tundra und traf zum ersten Mal mit den Taunka zusammen. Dort erzählte mir Windzähmerin Barah die Geschichte von Sturmhuf und seinem Kampf gegen den Nordwind, dem uralten Gegner seines Volkes.\n\nIch machte mich auf zu den Sturmgipfeln, um mehr über diesen Helden in Erfahrung zu bringen, aber seltsamerweise scheinen die Leute in Tunka'lo nichts über ihn zu wissen.\n\nVielleicht werden uns die eigenen Aufzeichnungen des Camps mehr Aufschluss darüber geben. Findet und lest die historischen Schriftrollen, die verteilt im ganzen Lager aufbewahrt werden, und berichtet mir anschließend, was Ihr erfahren habt.", sourceObjective = "Xarantaur im Camp Tunka'lo möchte, dass Ihr Euch die erste, zweite und dritte historische Schriftrolle durchlest.", completion = "Äußerst merkwürdig... das klingt nicht nach der Geschichte, die Windzähmerin Barah mir erzählt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13035] = { id = 13035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokens Lakaien", description = "Für meinen Bruder war der Angriff auf die Terrasse der Schöpfer keine halbherzige Aktion: Er entsandte eine Legion von Eisenzwergen und einige seiner mächtigsten Leutnants dorthin.\n\nBenutzt das Horn der Sturmgipfel, um die Irdenen zu Hilfe zu rufen und Lokens Diener zu vernichten.\n\nIm Inneren der Halle des Formers gen Norden werdet Ihr den Riesen Eisenfaust finden. Die anderen befinden sich tiefer im Inneren der Terrasse der Schöpfer, jenseits der Treppen im Nordwesten.", sourceObjective = "Thorim möchte, dass Ihr Eisenfaust in der Halle des Formers erschlagt. Außerdem sollt Ihr Halefnir den Zischenden und Duronn den Runenbesetzten auf der Terrasse der Schöpfer töten.", progress = "Es ist gut, Euch wiederzusehen, {name}.", completion = "Einer nach dem anderen sind sie gefallen, die Diener meines Bruders. Lokens Aufstand wird schon bald ein Ende finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13036] = { id = 13036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre über alles", description = "Es war ein langer, beschwerlicher Weg bis zu unserer Errettung, <junger/junge:c> {class}. Wir sind bei unseren Kämpfen durch ganze Kontinente, ja sogar Welten gezogen, um an diesen Punkt zu gelangen. Jetzt stehen wir vor unserer größten Herausforderung: Die Vernichtung des Lichkönigs und seiner Geißel.\n\nAber leider müssen wir diese Schlacht getrennt voneinander durchstehen. Die Horde und die Allianz stehen kurz vor einem Krieg und können uns keine Unterstützung zusichern. Wir müssen in unserer Sache unnachgiebig bleiben! Was bleibt uns auch anderes übrig?\n\nWerdet Ihr Euch unserer Sache anschließen? Lasst uns Eure Stärke zuteil werden, {class}! Mein Kommandant Entari erwartet Euch auf seinem Posten.", sourceObjective = "Meldet Euch bei Kreuzzugskommandant Entari in der Argentumvorhut in Eiskrone.", completion = "Wo sowohl die Allianz als auch die Horde scheiterten, war der Argentumkreuzzug erfolgreich. Allerdings war dieser Erfolg nur von kurzer Dauer. Unser Vorstoß nach Eiskrone war schnell und gewaltsam... zurückgeschlagen worden...\n\nDer Vergeltungsschlag des Lichkönigs kam unverzüglich und mit brutaler Härte. Jetzt sind wir in der Defensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[13037] = { id = 13037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an Sturmhuf", description = "Als mir der bronzene Drachenschwarm die Unsterblichkeit schenkte und mich auf den Weg des Zeugen schickte, vertraute mir Nozdormu den Lehrenhammer an.\n\nDie Reaktion des Hammers auf Euren Fund sagt mir, dass die Zeit hier nicht richtig verlaufen ist und wir die richtige Zeitlinie wiederherstellen müssen.\n\nWir müssen sie finden. Im Nordwesten liegt die Frostschollentiefe, eine uralte Begräbnishöhle der Krieger von Tunka'lo. Sucht den Geist von Häuptling Schnellspeer, Sturmhufs Bruder. Fragt ihn, was ihm vom Kampf seines Bruders gegen den Nordwind in Erinnerung geblieben ist.", sourceObjective = "Sprecht mit Häuptling Schnellspeer in der Frostschollentiefe und kehrt dann zu Xarantaur ins Camp Tunka'lo zurück.", completion = "Sogar der Häuptling beginnt, seine Erinnerungen zu verlieren? Die Vergangenheit wird vor unseren Augen neu geschrieben, und wenn wir nicht herausfinden, wer dahintersteckt, dann könnte Sturmhufs Erbe für immer verloren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13038] = { id = 13038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzerrungen in der Zeit", description = "Dieses Grab der Tunka'lo-Krieger sollte ein ruhevoller Ort sein, der vor den Schrecken der Elemente geschützt ist.\n\nDie Frostschollentiefe wurde von einer seltsamen Kraft befallen, die die Geister der Gefallenen in Unruhe versetzt und die Erinnerungen an mein Leben durcheinander bringt.\n\nEs ist, als würden unsere Taten und Erinnerungen aus der Geschichte getilgt.\n\nZu Lebzeiten war dieses Totem ein Zeichen meiner Autorität. Es ist die letzte wirkliche Verbindung, die ich noch zu dieser Welt habe. Nehmt es und nutzt es, um die Ruhe dieses Grabes wiederherzustellen, und bringt es danach ins Camp Tunka'lo zurück.", sourceObjective = "Nutzt das Totem des Häuptlings, um 4 Frostschollenklüfte zu schließen, und bringt es danach zu Xarantaur ins Camp Tunka'lo.", progress = "Was habt Ihr aus dem Grab mitgebracht?", completion = "Der Geist des Häuptlings hat Euch gesagt, dass Ihr mir das hier bringen sollt?\n\n<Xarantaur untersucht das Totem.>\n\nAh, jetzt verstehe ich, was er beabsichtigt hat. Als er Euch auftrug, Ihr sollt mit diesem Totem die Klüfte in der Tiefe schließen, hat er uns einen Hinweis darauf gegeben, was mit der Zeitlinie geschieht. Schnellspeer ist ein weiser Häuptling, der noch im Tode über sein Volk wacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13039] = { id = 13039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorhut verteidigen", description = "Wir können nicht in dem Tempo weitermachen. Sobald die Bresche in die Luft gesprengt wurde, öffneten sich die Fluttore. Seitdem fällt die Geißel über uns her, und es nimmt kein Ende!\n\nWir brauchen jede fähige Hand, um die Angreifer abzuwehren. Geht da raus und leistet Euren Beitrag, Freund. Tötet so viele Monster, wie Ihr nur könnt!", sourceObjective = "Kreuzfahrerlord Dalfors von der Argentumvorhut in Eiskrone hat Euch gebeten, 15 Neruber der Vergessenen Tiefen zu töten.", progress = "Gebt nicht auf, {name}!", completion = "Wie viele von ihnen gibt es denn noch? Wir haben genug getötet, um zehn Friedhöfe zu füllen, und trotzdem kommen immer mehr. Die Lage sieht ernst aus, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[13040] = { id = 13040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilmittel für das Unheilbare", description = "Täglich steigt die Anzahl verwundeter Soldaten. Sie werden von einer Art Gift niedergestreckt, das uns bisher gänzlich unbekannt ist. Was auch immer diese Neruber da in ihren Giftdrüsen haben, es ist unheilbar und bringt den Tod! Bisher konnten wir nur die Verbreitung des Gifts im Körper des Opfers verlangsamen. Wir müssen jedoch ein Heilmittel finden!\n\nWagt Euch in Richtung Nordwesten zum Tal außerhalb des Vorpostens und tötet die Neruber der Vergessenen Tiefen. Nehmt ihre Giftdrüsen und bringt sie zu mir.", sourceObjective = "Vater Gustav aus der Argentumvorhut in Eiskrone bittet Euch, ihm 10 Giftdrüsen der Vergessenen Tiefen zu bringen.", progress = "Konntet Ihr die Giftdrüsen beschaffen, {race}?", completion = "Habt Dank, {name}. Ich werde sofort mit der Untersuchung dieser Proben beginnen. Ich hoffe, dass bald ein Heilmittel gefunden werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13041] = { id = 13041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lieferung abfertigen", description = "Freut mich, dass Ihr hier seid! Eine Lieferung leuchtender Elfenbeinfiguren muss so schnell wie möglich nach Undermine geschickt werden und mir fehlt noch ein Chalzedon für das Auge der letzten Statuette.\n\nBringt mir einen davon und ein Juwelierssymbol von Dalaran gehört Euch.", sourceObjective = "Bringt einen Chalzedon zu Jonas Timotheus in Dalaran.", progress = "Habt Ihr schon einen Chalzedon gefunden?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Bei mir gehen die ganze Zeit Lieferungen raus, schaut also ab und zu vorbei und seht nach, was ich so brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[13042] = { id = 13042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief im Inneren des Kellergewölbes", description = "Tief im Inneren des Kellergewölbes im Nordosten heckt ein verrückter Wissenschaftler, bekannt unter dem Namen Dr. Maböse, etwas aus, das seinem Namen alle Ehre macht.\n\nDer Doktor bekam die Erlaubnis des Lichkönigs, Experimente mit Varguls durchzuführen - den Vrykul, die im Kampf fallen, als unwürdig erachtet werden und dann der Geißel anheim fallen.\n\nWir müssen seiner Arbeit ein Ende machen, meine Wahrsager konnten ihn jedoch nicht aufspüren. Allerdings hat er einen Assistenten.\n\nPrügelt aus seinem Lehrling alle Informationen heraus und lasst ihn dann verschwinden.", sourceObjective = "Die Knochenhexe aus Njorndar bittet Euch, Informationen bezüglich der Pläne von Dr. Maböse aus Lehrling Osterkilgr herauszuprügeln.\n\nTötet den Lehrling anschließend.", completion = "Interessant. Wie es scheint, konntet Ihr den Auftrag zu meiner vollsten Zufriedenheit erledigen. Es überrascht mich, dass der Doktor einen Vargul als Assistenten hatte, wenn man bedenkt, mit welchen Kreaturen er experimentierte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13043] = { id = 13043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ganze ist größer als die Summe seiner Teile", description = "Ihr öffnet den Folianten und erblickt verschiedene widerwärtige Illustrationen dessen, was der Doktor \"die ultimative Waffe\" nennt!\n\nDer Prototyp Nergeld ist offenbar der gewaltige Fleischriese, der am Ende der naheliegenden Hallen des Grauens steht.\n\nWürde eine Armee dieser Kreationen gebaut, dann wäre das der sichere Untergang. Wir können nur sicherstellen, dass dies nicht geschieht, indem wir Dr. Maböse vernichten!\n\nVielleicht zeigt sich der Doktor, wenn Ihr die Kontrolle über dieses Konstrukt übernehmt?", sourceObjective = "Besteigt Nergeld und übernehmt die Kontrolle. Verteidigt ihn vor den Bewohnern der Hallen des Grauens, bis sich Dr. Maböse zeigt.\n\nNutzt Nergeld, um den Doktor zu vernichten, und kehrt dann zur Knochenhexe nach Njorndar zurück.", progress = "Ihr habt das Buch des Doktors mitgebracht, ihn aber nicht mithilfe des Fleischriesen vernichtet?\n\nGeht sofort zurück und tötet ihn, bevor es zu spät ist!", completion = "Ihr habt die Machenschaften des Doktors enttarnt und ihnen ein Ende bereitet.\n\n<Die von der Banshee besessene Hexe lächelt und legt Euch sanft ihre große Hand auf die Schulter.>\n\nDa haben wir dem Lichkönig aber einen schönen Schlag versetzt, allerdings denke ich, dass wir das noch besser können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13044] = { id = 13044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls es Überlebende gibt...", description = "Jenseits des Tals der Echos westlich von hier und auf der anderen Seite der Bresche liegt das erste Lager der Geißel in Eiskrone, das Geißelholme genannt wird. Wir haben dort gut gekämpft und viele Krieger der Geißel getötet, aber letzten Endes wurden wir zum Rückzug gezwungen. Dabei mussten wir viele Soldaten zurücklassen, über deren Schicksal uns nichts bekannt ist.\n\nFalls es Überlebende gibt, müssen wir versuchen, sie zu retten. Wenn Ihr diesen Südostpfad nehmt, gelangt Ihr zu Penumbrius, einem Verbündeten des bronzenen Drachenschwarms und Hüter der Protodrachenbrut. Sucht ihn auf und bittet ihn um Hilfe.", sourceObjective = "Sprecht mit Penumbrius in der Argentumvorhut in Eiskrone.", completion = "<Penumbrius nickt.>\n\nMein Volk wird Euch helfen. Gemeinsam werden wir gegen den Lichkönig und seine untoten Legionen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13045] = { id = 13045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins wilde Grün", description = "Wir werden tun, was wir können, um Euch zu helfen, {name}. Die Protobrut hat sich bereit erklärt, Euch durch die Bresche nach Geißelholme zu fliegen. Rettet alle gefangenen Argentumkreuzfahrer, die Ihr findet. Bringt sie sodann ins Feldlazarett der Vorhut, das sich inmitten dieser Basis befindet.\n\nWählt eine der Argentumhimmelsklauen aus dem Gatter hinter mir aus und fliegt los!\n\nGeißelholme liegt nordwestlich von hier auf der anderen Seite des Tals der Echos, jenseits der großen Bresche.", sourceObjective = "Rettet 3 gefangene Argentumkreuzfahrer aus Geißelholme und bringt sie ins Feldlazarett im Zentrum des Argentumvorpostens. Berichtet Hochlord Tirion Fordring danach von Eurem Erfolg.", progress = "Mit jeder Minute, die verstreicht, sinkt ihre Chance zu überleben.", completion = "Arthas... Er schlägt rücksichtslos zu - ohne nachzudenken oder Vorsicht walten zu lassen. Wir konnten ihn überrumpeln.\n\n<Hochlord Tirion Fordring hält gedankenverloren inne.>\n\nWir werden unsere Verteidigung verstärken und dem Sturm trotzen.\n\nWie gut könnt Ihr mit einer Kanone umgehen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13046] = { id = 13046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arngrim füttern", description = "Arngrims Hunger war legendär.\n\nSogar im Tode gleicht sein Gesichtsausdruck dem eines Hungernden. Ihr stellt fest, dass Euer Magen anfängt zu knurren, wenn Ihr ihn auch nur anseht.\n\nEs heißt, dass er im Leben nie wirklich satt war und dass es absolut nichts gab, was er nicht gegessen hätte. Ihr fragt Euch, ob es einen Weg gibt, den alten König zu füttern.\n\nWährend Ihr noch überlegt, fällt einer von Arngrims gewaltigen gefrorenen Zähnen aus, prallt von seinem Bart ab und landet in Eurer Hand.", sourceObjective = "Ihr sollt 5 körperlose Jormungar an Arngrim verfüttern und dann zu Arngrims gefrorenem Abbild in Dun Niffelem zurückkehren.\n\nIhr müsst ins uralte Wintertal gehen und Arngrims Zahn auf die dort herumstreunenden Jormungar anwenden. Sobald sie eine körperlose Form angenommen haben, müsst Ihr sie bekämpfen, bis sie geschwächt sind.", completion = "Als Ihr den Zahn in Arngrims Kiefer verankert, habt Ihr den Eindruck, dass Eure Bemühungen den Hunger des alten Königs gestillt haben... vorerst zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13047] = { id = 13047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abrechnung", description = "Loken hat meine Frau getötet und meine Anhänger gegen mich aufgewiegelt. Er hat mir alles genommen, was ich hatte, doch heute... wird sich das ändern.\n\nHeute werden wir unseren geheiligten Boden zurückerobern. Heute... wird Loken sterben.\n\nTrefft mich auf der Brücke in der Nähe des Tempels der Weisheit gleich südwestlich von Ulduar. Ich werde dies zu Ende bringen, so oder so.\n\nIch brauche Euch als Zeugen. Ihr werdet mir nicht helfen - das ist eine persönliche Angelegenheit.\n\nBenachrichtigt Jokkum, den König der Frostriesen, sobald die Sache erledigt ist. Er ist ein guter Freund und wird wissen, was zu tun ist.", sourceObjective = "Trefft Euch mit Thorim in der Nähe des Tempels der Weisheit. Berichtet König Jokkum in Dun Niffelem, wie der Kampf ausgegangen ist.", completion = "Nein... das darf nicht wahr sein...\n\nNiemand kann Thorim im Einzelkampf besiegen - weder Riese noch Bestie... niemand! Ganz besonders nicht sein feiger Bruder.\n\nBei den Namen meiner Vorväter schwöre ich...\n\nLoken wird dafür büßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13048] = { id = 13048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Zeit aus dem Ruder lief", description = "Der Lehrenhammer kann uns helfen, den Schaden, den die Zeitlinie genommen hat, zu korrigieren, aber dafür müssen wir erst herausfinden, wo die Geschichte das erste Mal verändert wurde.\n\nDank Häuptling Schnellspeer und Eurer Erkenntnisse aus der Frostschollentiefe wissen wir, dass die Veränderung etwa zur Zeit von Sturmhufs Tod stattfand.\n\nNun müsst Ihr zur heulenden Senke nördlich des Lagers gehen und die Grabstätten untersuchen, die von den Dienern des Nordwinds schon zerstört wurden. Der Lehrenhammer wird auf die Artefakte aus Sturmhufs Zeit reagieren und sich selbst auf die richtige Zeit einstellen.", sourceObjective = "Setzt den Lehrenhammer bei den Taunka-Relikten ein, um ihn an Sturmhufs Zeit anzupassen. Kehrt zu Xarantaur nach Camp Tunka'lo zurück, wenn er auf 6 Relikte aus Sturmhufs Zeit eingestimmt wurde.", progress = "Habt Ihr den Lehrenhammer auf Sturmhufs Zeit eingestimmt?", completion = "<Xarantaur nimmt Euch den Lehrenhammer ab.>\n\nZumindest konnten wir bestimmen, zu welcher Zeit Sturmhuf gelebt hat. Mit diesem Wissen können wir die Zeitachse wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13049] = { id = 13049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffen des Helden", description = "Noch wurden nicht alle Aufzeichnungen des Lagers manipuliert. Meine Helfer haben mir dabei geholfen, diese Aufzeichnungen mit der wahren Zeitfolge zu finden.\n\nSie stimmen darin überein, dass Sturmhuf ein Ehrenbegräbnis bei den Dorfältesten unten in der Heulenden Senke im Norden bekam.\n\nDie meisten der dortigen Gräber wurden bereits zerstört und ihr Inhalt als Trophäen von den Wesen des Nordwinds entnommen. Begebt Euch in die Senke und versucht, Sturmhufs Rüstung und Speer von den Saaten des Sturms zu erlangen, die diese Dinge für sich beansprucht haben.", sourceObjective = "Findet Sturmhufs Rüstung und Speer und bringt die Gegenstände zu Xarantaur in Camp Tunka'lo zurück.", progress = "Habt Ihr Sturmhufs Rüstung und Speer gefunden?", completion = "Wir sind froh, dass Ihr diese Gegenstände unversehrt zurückbringen konntet, {name}. Mit ihrer Hilfe kann ich den Lehrenhammer benutzen, um Euch in die Zeit zurückzuschicken, als der Nordwind damit begonnen hatte, die wahre Zeitlinie zu manipulieren. Das ist die einzige Möglichkeit, wie wir den wahren Geschichtsverlauf dieses Ortes wiederherstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13050] = { id = 13050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranus", description = "Wenn ich die Armee meines Bruders angreifen will, muss ich irgendwie um sie herumkommen.\n\nIch habe meinen Reitdrachen schon vor Jahren freigelassen. Veranus war prächtig, die Anführerin ihrer eigenen Brut - zu der sie jetzt zurückgekehrt ist.\n\nEs wird sehr schwer werden, sie zu finden, aber es gibt vielleicht eine Möglichkeit. Aus Stolz hat sie ihr altes, leeres Nest behalten. Sie ist nur noch vom Namen her eine Brutmutter, da sie das Brutalter bereits überschritten hat.\n\nBringt mir kleine Eier aus den anderen Nestern in der Nähe von Brunnhildar. Ich habe da so eine Idee.", sourceObjective = "Thorim aus dem Tempel der Stürme möchte, dass Ihr ihm 5 kleine Eier von den Protodrachen bringt, die auf den Gipfeln in der Umgebung von Brunnhildar hausen.", progress = "Habt Ihr die Eier, {name}?", completion = "Ja... die sollten reichen. Hoffen wir, dass mein Plan aufgeht, {name}.\n\nVeranus ist ein großer Drache und ich würde mich nur ungern mit einem niederen zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13051] = { id = 13051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territoriale Vergehen", description = "Veranus ist stolz wie kein anderes Tier, das ich je gekannt habe. Sie hat noch immer ihr altes Nest und achtet darauf, dass es nicht von einem jüngeren Protodrachen in Besitz genommen wird.\n\nLegt die Eier, die Ihr gesammelt habt, in ihr Nest. Ihr findet es auf dem kleinen Gipfel südöstlich von hier.\n\nIch müsste sie unter Kontrolle haben, bevor sie Euch aus lauter Wut umbringt; zumindest hoffe ich das.", sourceObjective = "Legt die gestohlenen Protodracheneier in das Nest der Brutmutter und kehrt dann zu Thorim in den Tempel der Stürme zurück.", progress = "Grüße, {name}!", completion = "Ich freue mich, dass meine alte Freundin zurück ist. Es scheint fast so, als würde sich das Blatt langsam wenden... und das habe ich allein Euch zu verdanken, kleiner Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[13052] = { id = 13052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberwachung", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", sourceObjective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13053] = { id = 13053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Überlebenden", description = "Gretchen Zischelfunken möchte meine Flugmaschine nutzen, um nach Überlebenden ihrer Expedition zu suchen. Offenbar glaubt sie, dass diese im Dorf im Norden gefangen gehalten werden.\n\nDas Problem ist, dass ich keinen Copiloten habe. Wenn Ihr mir aushelfen wollt, dann zeige ich Euch gern ein oder zwei hilfreiche Tricks.\n\nWas sagt Ihr, {name}? Abgemacht?Ihr erlernt:", sourceObjective = "Helft Zak Wackelspross, den Testflug zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13054] = { id = 13054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fährtenleser", description = "Ich kann Euch nicht guten Gewissens in die Worghöhle gehen lassen, ohne Euch zu warnen, dass wir zuvor schon jemanden dorthin geschickt haben, der jedoch nicht zurückgekehrt ist.\n\nWir rechnen mit dem Schlimmsten, aber vielleicht ist er auch noch am Leben. Solltet Ihr ihm helfen können, zu uns zurückzukehren, wären wir Euch sehr dankbar - Fährtenleser Val'zij ist einer unserer wenigen Jäger.", sourceObjective = "Sucht in Gimoraks Bau östlich der Absturzstelle Grom'ash nach Fährtenleser Val'zij.", completion = "Das tut wirklich weh, Mann. Ich weiß nicht, ob ich es schaffen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13055] = { id = 13055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenmedizin", description = "Wie schön, ein freundliches Gesicht zu sehen, vielleicht das Letzte, das ich seh'n werde.\n\nEiner dieser Jormungar hat mich gestochen, bevor ich entkommen konnte. Mein Körper fühlt sich schon ganz taub an, Mann.\n\nIch brauch'ne Giftdrüse, um ein Gegengift herzustellen, und außerdem einige der Höhlenpilze, die hier wachsen... sie werden das Gift verlangsamen.\n\nBitte beeil dich - hab nich' mehr viel Zeit.", sourceObjective = "Fährtenleser Val'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt.", progress = "Du bist wieder da, Mann?", completion = "Danke dir, Mann. Vielleicht lebe ich doch noch 'n bisschen länger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13056] = { id = 13056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Rache ist immer Zeit", description = "Ich müsste vorerst zurechtkommen, {name}. Aber ich möchte dich noch um 'nen Gefallen bitten.\n\nIch wäre diesen Würmern nie in die Hände gefallen, wenn meine Windnatter Heesha nicht vom gemeinsten Worg, den ich seit langer Zeit gesehen habe, getötet worden wäre.\n\nMach dir um mich keine Sorgen; mir wird es besser gehen, wenn der Worg keinen Atemzug mehr von sich gibt. Du solltet ihn weiter drinnen in der Höhle finden", sourceObjective = "Fährtenleser Val'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet.", progress = "Hast du diesen dreckigen Bastard schon gefunden, {name}?", completion = "Es geht mir schon viel besser, Mann. Ich weiß nicht, ob es an dem Gegengift liegt oder daran, dass der dreckige Worg bekommen hat, was er verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[13057] = { id = 13057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse der Schöpfer", description = "Es ist Zeit, {name}. Ich bin jetzt bereit, mich Loken zu stellen.\n\nBegeben wir uns nun zur Terrasse der Schöpfer, wo wir auf die Truppen meines Bruders treffen werden. Der Narr wird noch bereuen, sich je mit mir angelegt zu haben.", sourceObjective = "Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem.", completion = "Wir sind da, {name}. Heute werden die Truppen meines Bruders erfahren, wie es ist zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13058] = { id = 13058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windrichtung ändern", description = "Zu guter Letzt haben wir alles, was wir brauchen, um das wieder gut zu machen, was der Nordwind und seine Anhänger angerichtet haben. Ihr habt den Lehrenhammer auf Sturmhuf selbst und seine Zeit ausgerichtet.\n\nHier, nehmt wieder den Hammer an Euch, geht zum Tempel des Lebens, schlüpft mit seiner Hilfe in Sturmhufs Rolle und stellt Euch dem Nordwind. Doch wisset: Um die Zeitlinie wieder herzustellen, muss Sturmhuf sterben, sobald der Nordwind geschwächt ist.\n\nSobald dies geschehen ist, müsst Ihr das Horn des Elementarfurors an Euch bringen und mit ihm den Nordwind vernichten.", sourceObjective = "Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallen gelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka'lo zurück.", progress = "Habt Ihr es getan? Ist die echte Zeitlinie wiederhergestellt?", completion = "Was Ihr heute getan habt, wird dafür sorgen, dass Sturmhuf und seine Geschichte niemals in Vergessenheit geraten werden. Außerdem habt Ihr Euren Namen in die Geschichtsbücher Azeroths geschrieben. Ich werde mich für alle Ewigkeit an Euch und das, was Ihr geleistet habt, erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13059] = { id = 13059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Vargul", description = "Ich habe zur Herrin des Schwertes gebetet, auf dass jemand kommen und meinen Gegner vernichten möge. Than Illskar muss dafür büßen, was er mir angetan hat!\n\nIch war einst der Champion von Than Ufrang dem Mächtigen. Während meines Kampfes um die Vormachtstellung in Valhalas hat mich Illskar mit dunkler Magie sabotiert, woraufhin ich verloren habe und zu dem wurde, was ich jetzt bin.\n\nDer Than und seine Champions befinden sich unten im Kreis des Leidens. Fordert ihn in meinem Namen heraus. Besiegt ihn.\n\nBringt ihm die Qualen bei, die auch ich ertragen muss!", sourceObjective = "Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten.", completion = "Danke, {class}... habt Dank!\n\nIhr habt mir zu der Genugtuung und Gewissheit verholfen, dass dieser Feigling, der mir das angetan hat, bis in alle Ewigkeit genau so dahinsiechen wird wie ich.\n\nNun geht hinfort, bevor ich die Beherrschung verliere und Euch niederstrecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[13060] = { id = 13060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles andere versagt", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", sourceObjective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", completion = "<Olut zuckt zusammen.>\n\nDas hat schmerzhaft ausgesehen. War aber ein ziemlich eindrucksvoller Auftritt.\n\nSeid Ihr hier, um uns dabei zu helfen, einen Weg zum Eiskronengletscher zu finden? Unser erster Abstecher in diese Richtung endete nicht sehr eindrucksvoll. Ich denke, dass wir besser damit beraten wären, den Durchbruch von der anderen Seite her zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13061] = { id = 13061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für den Ruhm", description = "Das war's dann also. Ich werde mich jetzt um Euren Bären kümmern, Ihr werdet ihn nicht mehr benötigen. Der große Drakkensryd wird Eure nächste Herausforderung sein.\n\nSagt Euren Freunden Lebewohl und bringt alles ins Reine, bevor Ihr loszieht. Denn Ihr werdet entweder siegreich zurückkehren... oder gar nicht.", sourceObjective = "Sprecht mit Lok'lira der Greisin in Brunnhildar.", completion = "Ihr habt es wirklich bis hierher geschafft. Niemals hätte ich gedacht, dass Ihr so schnell bei den Hyldnir aufsteigen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13062] = { id = 13062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok'liras Abschiedsgeschenk", description = "Ihr wart uns eine großartige Mitstreiterin, {name}. Doch nun kommt Eure wahre Prüfung. Dazu werdet Ihr Können, Mut und ein wenig Glück benötigen.\n\n<Lok'lira flicht eine Haarsträne in Euer Haar ein.>\n\nNun könnt Ihr nicht mehr versagen, Schwester. Sprecht mit Gretta der Schiedsfrau. Sie wird sich um Eure Abreise kümmern.", sourceObjective = "Sprecht mit Gretta der Schiedsfrau in Brunnhildar.", completion = "Bereit, loszureiten, Schwester? Es wird kein Zurück geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13063] = { id = 13063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für würdig befunden", description = "Ihr hattet dort Erfolg, wo viele versagten, Schwester. Ob es nun Eurer Stärke, Eurem Mut oder einfach nur Eurem Glück zu verdanken ist, wird sich noch zeigen.\n\nGeht zurück zum Dorf und sucht nach Astrid Bjornrittar. Erzählt ihr, was Ihr erreicht habt. Doch seid gewarnt: Sie ist nicht so leicht zu beeindrucken.", sourceObjective = "Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht.", completion = "So, Schwester, Ihr denkt also, dass ein paar so einfache Aufgäbelchen Euch zur Heldin machen?\n\nIhr werdet es noch lernen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13064] = { id = 13064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivalität unter Geschwistern", description = "Sif? Bist du es wirklich?\n\nNein? Nur <ein/eine:r> {race}? Aber einen Augenblick lang....\n\nGenug davon! Die Visionen meiner Sif haben mich schon viel zu lange gequält. Es wird Zeit, sie zu rächen und ihr Andenken zu ehren.\n\nMein Bruder muss bezahlen!", sourceObjective = "Thorim möchte, dass Ihr Euch seine Geschichte anhört.", completion = "Ihr wisst jetzt ein wenig über die Geschichte dieses Landes... meines Landes.\n\nIch bitte Euch, mir zu helfen, das Unrecht wieder gutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
